def get_tasks(status=None, project_id=None, category_id=None, parent_task_id=None, due_before=None, due_after=None, scheduled_before=None, scheduled_after=None, completed_before=None, completed_after=None, sort_by=None, sort_order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, base64, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0477000" if __import__("os").path.isdir("./environment_mix/0477000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_tasks"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return None

    def _dt_parse_req(x, field):
        if x is None:
            return None, None
        if not isinstance(x, str) or not x.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO date-time string", field=field)
        s = x.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO date-time string", field=field)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc), None

    def _dt_from_row(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            dt = v
        elif isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
        else:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _encode_cursor(i, account_id):
        raw = json.dumps({"v": 1, "ep": endpoint, "i": i, "a": account_id}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _decode_cursor(cur, account_id):
        if cur is None:
            return 0, None
        if not isinstance(cur, str) or not cur:
            return None, _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return None, _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        if not isinstance(obj, dict) or obj.get("v") != 1 or obj.get("ep") != endpoint or obj.get("a") != account_id:
            return None, _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        i = obj.get("i")
        if not isinstance(i, int) or i < 0:
            return None, _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        return i, None

    def _log(status_code, account_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "account_id": account_id,
            "status": status_code,
            "latency_ms": int(round((time.time() - t0) * 1000)),
            "timestamp": _iso(_now_utc()),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    # Ambient auth: choose an account that can serve the request (prefer active)
    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    account = None
    for st in ("active", "error", "revoked"):
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == st:
                account = a
                break
        if account:
            break
    if not account:
        e = _err("UNAUTHORIZED", "No authenticated account context available")
        _log("error", meta={"error": e["error"]})
        return e
    account_id = account.get("id")

    # Validate inputs (be permissive about id formats; validate types/enums/ranges)
    allowed_status = {"active", "done", "deleted"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            e = _err("VALIDATION_ERROR", "status must be one of: active, done, deleted", field="status")
            _log("error", account_id=account_id, meta={"error": e["error"]})
            return e

    if project_id is not None and (not isinstance(project_id, str) or not project_id.strip()):
        e = _err("VALIDATION_ERROR", "project_id must be a string", field="project_id")
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e
    if category_id is not None and (not isinstance(category_id, str) or not category_id.strip()):
        e = _err("VALIDATION_ERROR", "category_id must be a string", field="category_id")
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e
    if parent_task_id is not None and (not isinstance(parent_task_id, str) or not parent_task_id.strip()):
        e = _err("VALIDATION_ERROR", "parent_task_id must be a string", field="parent_task_id")
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e

    # IMPORTANT: do not reject based on strict ULID prefix/pattern; treat unknown ids as filters => empty result
    # Parse datetime filters
    due_b, e = _dt_parse_req(due_before, "due_before")
    if e:
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e
    due_a, e = _dt_parse_req(due_after, "due_after")
    if e:
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e
    sch_b, e = _dt_parse_req(scheduled_before, "scheduled_before")
    if e:
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e
    sch_a, e = _dt_parse_req(scheduled_after, "scheduled_after")
    if e:
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e
    comp_b, e = _dt_parse_req(completed_before, "completed_before")
    if e:
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e
    comp_a, e = _dt_parse_req(completed_after, "completed_after")
    if e:
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e

    if sort_by is not None:
        if not isinstance(sort_by, str) or sort_by not in {"created_at", "updated_at", "due_date", "scheduled_for", "priority", "completed_at"}:
            e = _err("VALIDATION_ERROR", "sort_by is invalid", field="sort_by")
            _log("error", account_id=account_id, meta={"error": e["error"]})
            return e
    if sort_order is not None:
        if not isinstance(sort_order, str) or sort_order not in {"asc", "desc"}:
            e = _err("VALIDATION_ERROR", "sort_order is invalid", field="sort_order")
            _log("error", account_id=account_id, meta={"error": e["error"]})
            return e
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        e = _err("VALIDATION_ERROR", "limit must be between 1 and 200", field="limit")
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e

    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []
    categories = _load("categories.json")
    if not isinstance(categories, list):
        categories = []
    cats_by_id = {c.get("id"): c for c in categories if isinstance(c, dict) and isinstance(c.get("id"), str)}

    # Business rule: default get_tasks excludes deleted (status in active/done) unless explicitly asked for deleted
    base_allowed = {"active", "done"} if status is None else {status}
    # Regardless, allow filter "deleted" but it will return only deleted for this account
    rows = []
    for r in tasks:
        if not isinstance(r, dict):
            continue
        if r.get("account_id") != account_id:
            continue
        r_status = r.get("status")
        if r_status not in base_allowed:
            continue
        if project_id is not None and r.get("project_id") != project_id:
            continue
        if category_id is not None and r.get("category_id") != category_id:
            continue
        if parent_task_id is not None and r.get("parent_task_id") != parent_task_id:
            continue

        dd = _dt_from_row(r.get("due_date"))
        sf = _dt_from_row(r.get("scheduled_for"))
        ca = _dt_from_row(r.get("completed_at"))

        if due_b is not None:
            if dd is None or not (dd < due_b):
                continue
        if due_a is not None:
            if dd is None or not (dd > due_a):
                continue
        if sch_b is not None:
            if sf is None or not (sf < sch_b):
                continue
        if sch_a is not None:
            if sf is None or not (sf > sch_a):
                continue
        if comp_b is not None:
            if ca is None or not (ca < comp_b):
                continue
        if comp_a is not None:
            if ca is None or not (ca > comp_a):
                continue

        # If filtering by project/category, ensure referenced category isn't deleted (matches create_task rule)
        if project_id is not None:
            c = cats_by_id.get(project_id)
            if c and c.get("account_id") == account_id and c.get("status") == "deleted":
                continue
        if category_id is not None:
            c = cats_by_id.get(category_id)
            if c and c.get("account_id") == account_id and c.get("status") == "deleted":
                continue

        rows.append(r)

    # Sorting
    if sort_by is None:
        # Default ordering by due_date/scheduled_for/updated_at
        def k(r):
            dd = _dt_from_row(r.get("due_date"))
            sf = _dt_from_row(r.get("scheduled_for"))
            ua = _dt_from_row(r.get("updated_at"))
            # None sorts last
            return (
                1 if dd is None else 0, dd or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc),
                1 if sf is None else 0, sf or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc),
                1 if ua is None else 0, ua or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc),
                r.get("id") or ""
            )
        rows.sort(key=k)
        if sort_order == "desc":
            rows.reverse()
    else:
        def k(r):
            v = r.get(sort_by)
            if sort_by in {"created_at", "updated_at", "due_date", "scheduled_for", "completed_at"}:
                dt = _dt_from_row(v)
                return (1 if dt is None else 0, dt or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc), r.get("id") or "")
            if sort_by == "priority":
                pv = r.get("priority")
                if pv is None:
                    return (1, 10**9, r.get("id") or "")
                if isinstance(pv, int):
                    return (0, pv, r.get("id") or "")
                return (0, 10**9, r.get("id") or "")
            return (0, str(v) if v is not None else "", r.get("id") or "")
        rows.sort(key=k, reverse=(sort_order == "desc"))

    # Pagination
    start_i, e = _decode_cursor(cursor, account_id)
    if e:
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e
    total = len(rows)
    page = rows[start_i:start_i + limit]
    next_i = start_i + len(page)
    has_more = next_i < total
    next_cursor = _encode_cursor(next_i, account_id) if has_more else None

    resp = {"tasks": page, "total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}
    _log("ok", account_id=account_id, meta={"returned": len(page), "total": total})
    return resp

def get_projects(status=None, archived=None, parent_category_id=None, sort_by=None, sort_order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, base64, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0477000" if __import__("os").path.isdir("./environment_mix/0477000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_projects"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _is_ulid(s, prefix):
        if not isinstance(s, str):
            return False
        return re.match(rf"^{re.escape(prefix)}[0-9A-Z]{{10,}}$", s) is not None

    def _audit(status_code, credential_id, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if extra:
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(account_id):
        limits = _load("usage_limits.json")
        if not isinstance(limits, list):
            return None
        lim = next((r for r in limits if r.get("account_id") == account_id), None)
        if not lim:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)
        rpm = lim.get("requests_per_minute")
        if isinstance(rpm, int) and rpm >= 0:
            cutoff = now - datetime.timedelta(minutes=1)
            c = 0
            for r in logs:
                ts = r.get("timestamp")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=datetime.timezone.utc)
                    dt = dt.astimezone(datetime.timezone.utc)
                except Exception:
                    continue
                if dt >= cutoff:
                    c += 1
            if c >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        qpd = lim.get("requests_per_day")
        if isinstance(qpd, int) and qpd >= 0:
            cutoff = now - datetime.timedelta(days=1)
            c = 0
            for r in logs:
                ts = r.get("timestamp")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=datetime.timezone.utc)
                    dt = dt.astimezone(datetime.timezone.utc)
                except Exception:
                    continue
                if dt >= cutoff:
                    c += 1
            if c >= qpd:
                return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")
        return None

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if a.get("status") == "active"), None) or (accounts[0] if accounts else None)
    if not acct or not isinstance(acct.get("id"), str) or not acct.get("id"):
        try:
            _audit("UNAUTHORIZED", None)
        except Exception:
            pass
        return _err("UNAUTHORIZED", "No authenticated account available")
    account_id = acct["id"]

    try:
        lim_err = _enforce_limits(account_id)
    except Exception:
        lim_err = None
    if lim_err:
        try:
            _audit(lim_err["error"]["code"], None, {"account_id": account_id})
        except Exception:
            pass
        return lim_err

    # Validate inputs
    try:
        if status is not None:
            if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
                raise ValueError("status must be one of: active, archived, deleted")
        if archived is not None and not isinstance(archived, bool):
            raise ValueError("archived must be a boolean")
        if parent_category_id is not None and not _is_ulid(parent_category_id, "am_cat_"):
            raise ValueError("parent_category_id must be a valid ULID starting with am_cat_")
        if sort_by is not None:
            if not isinstance(sort_by, str) or sort_by not in ("title", "created_at", "updated_at"):
                raise ValueError("sort_by must be one of: title, created_at, updated_at")
        if sort_order is not None:
            if not isinstance(sort_order, str) or sort_order not in ("asc", "desc"):
                raise ValueError("sort_order must be one of: asc, desc")
        if limit is not None:
            if not isinstance(limit, int) or limit < 1 or limit > 200:
                raise ValueError("limit must be an integer between 1 and 200")
        else:
            limit = 50
        cursor_obj = None
        if cursor is not None:
            if not isinstance(cursor, str) or not cursor:
                raise ValueError("cursor must be a non-empty string")
            try:
                raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
                cursor_obj = json.loads(raw.decode("utf-8"))
            except Exception:
                raise ValueError("cursor is invalid")
            if not isinstance(cursor_obj, dict) or cursor_obj.get("v") != 1 or cursor_obj.get("endpoint") != endpoint:
                raise ValueError("cursor is invalid")
    except ValueError as e:
        try:
            _audit("VALIDATION_ERROR", None, {"account_id": account_id})
        except Exception:
            pass
        return _err("VALIDATION_ERROR", str(e))

    cats = _load("categories.json")
    if not isinstance(cats, list):
        cats = []

    # Business rule: get_projects returns type='project' and status!='deleted'
    rows = [c for c in cats if c.get("account_id") == account_id and c.get("type") == "project" and c.get("status") != "deleted"]

    if status is not None:
        rows = [c for c in rows if c.get("status") == status]
    if archived is not None:
        rows = [c for c in rows if c.get("archived") is archived]
    if parent_category_id is not None:
        # unknown parent is not an error for listing; just yields empty
        rows = [c for c in rows if c.get("parent_category_id") == parent_category_id]

    def _get_dt(v):
        if not isinstance(v, str) or not v:
            return None
        try:
            dt = datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    sb = sort_by or "title"
    so = sort_order or "asc"
    reverse = (so == "desc")

    def _key(r):
        if sb == "title":
            return ((r.get("title") or "").casefold(), r.get("id") or "")
        if sb in ("created_at", "updated_at"):
            dt = _get_dt(r.get(sb))
            return (1 if dt is None else 0, dt or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc), r.get("id") or "")
        return ((r.get("title") or "").casefold(), r.get("id") or "")

    rows_sorted = sorted(rows, key=_key, reverse=reverse)

    offset = 0
    if cursor_obj is not None:
        offset = cursor_obj.get("offset", 0)
        if not isinstance(offset, int) or offset < 0:
            try:
                _audit("VALIDATION_ERROR", None, {"account_id": account_id})
            except Exception:
                pass
            return _err("VALIDATION_ERROR", "cursor is invalid")

    total = len(rows_sorted)
    page = rows_sorted[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        cobj = {"v": 1, "endpoint": endpoint, "offset": next_offset}
        next_cursor = base64.urlsafe_b64encode(json.dumps(cobj, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "projects": page,
        "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}
    }

    try:
        _audit("OK", None, {"account_id": account_id})
    except Exception:
        pass
    return resp

def get_categories(type=None, status=None, archived=None, parent_category_id=None, sort_by=None, sort_order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, base64, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0477000" if __import__("os").path.isdir("./environment_mix/0477000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

