            logs = []
        row = {
            "id": f"req_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if extra:
            row.update(extra)
