        if isinstance(rpm, int) and rpm >= 0:
            cutoff = now - datetime.timedelta(minutes=1)
            c = 0
            for r in logs:
                ts = r.get("timestamp")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=datetime.timezone.utc)
                    dt = dt.astimezone(datetime.timezone.utc)
                except Exception:
                    continue
                if dt >= cutoff:
                    c += 1
            if c >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        qpd = lim.get("requests_per_day")
        if isinstance(qpd, int) and qpd >= 0:
            cutoff = now - datetime.timedelta(days=1)
            c = 0
            for r in logs:
                ts = r.get("timestamp")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=datetime.timezone.utc)
                    dt = dt.astimezone(datetime.timezone.utc)
                except Exception:
                    continue
                if dt >= cutoff:
                    c += 1
            if c >= qpd:
                return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")
        return None

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if a.get("status") == "active"), None) or (accounts[0] if accounts else None)
    if not acct or not isinstance(acct.get("id"), str) or not acct.get("id"):
        try:
            _audit("UNAUTHORIZED", None)
        except Exception:
            pass
        return _err("UNAUTHORIZED", "No authenticated account available")
    account_id = acct["id"]

    try:
        lim_err = _enforce_limits(account_id)
    except Exception:
        lim_err = None
    if lim_err:
        try:
            _audit(lim_err["error"]["code"], None, {"account_id": account_id})
        except Exception:
            pass
        return lim_err

    # Validate inputs
    try:
        if type is not None:
            if not isinstance(type, str) or type not in ("project", "category"):
                raise ValueError("type must be one of: project, category")
        if status is not None:
            if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
                raise ValueError("status must be one of: active, archived, deleted")
        if archived is not None and not isinstance(archived, bool):
            raise ValueError("archived must be a boolean")
        if parent_category_id is not None and not _is_ulid(parent_category_id, "am_cat_"):
            raise ValueError("parent_category_id must be a valid ULID starting with am_cat_")
        if sort_by is not None:
            if not isinstance(sort_by, str) or sort_by not in ("title", "created_at", "updated_at"):
                raise ValueError("sort_by must be one of: title, created_at, updated_at")
        if sort_order is not None:
            if not isinstance(sort_order, str) or sort_order not in ("asc", "desc"):
                raise ValueError("sort_order must be one of: asc, desc")
        if limit is not None:
            if not isinstance(limit, int) or limit < 1 or limit > 200:
                raise ValueError("limit must be an integer between 1 and 200")
        else:
            limit = 50
        cursor_obj = None
        if cursor is not None:
            if not isinstance(cursor, str) or not cursor:
                raise ValueError("cursor must be a non-empty string")
            try:
                raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
                cursor_obj = json.loads(raw.decode("utf-8"))
            except Exception:
                raise ValueError("cursor is invalid")
            if not isinstance(cursor_obj, dict) or cursor_obj.get("v") != 1 or cursor_obj.get("endpoint") != endpoint:
                raise ValueError("cursor is invalid")
    except ValueError as e:
        try:
            _audit("VALIDATION_ERROR", None, {"account_id": account_id})
        except Exception:
            pass
        return _err("VALIDATION_ERROR", str(e))

    cats = _load("categories.json")
    if not isinstance(cats, list):
        cats = []

    # Business rule: get_categories returns categories where status!='deleted'
    rows = [c for c in cats if c.get("account_id") == account_id and c.get("status") != "deleted"]

    if type is not None:
        rows = [c for c in rows if c.get("type") == type]
    if status is not None:
        rows = [c for c in rows if c.get("status") == status]
    if archived is not None:
        rows = [c for c in rows if c.get("archived") is archived]
    if parent_category_id is not None:
        rows = [c for c in rows if c.get("parent_category_id") == parent_category_id]

    def _get_dt(v):
        if not isinstance(v, str) or not v:
            return None
        try:
            dt = datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    sb = sort_by or "title"
    so = sort_order or "asc"
    reverse = (so == "desc")

    def _key(r):
        if sb == "title":
            return ((r.get("title") or "").casefold(), r.get("id") or "")
        if sb in ("created_at", "updated_at"):
            dt = _get_dt(r.get(sb))
            return (1 if dt is None else 0, dt or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc), r.get("id") or "")
        return ((r.get("title") or "").casefold(), r.get("id") or "")

    rows_sorted = sorted(rows, key=_key, reverse=reverse)

    offset = 0
    if cursor_obj is not None:
        offset = cursor_obj.get("offset", 0)
        if not isinstance(offset, int) or offset < 0:
            try:
                _audit("VALIDATION_ERROR", None, {"account_id": account_id})
            except Exception:
                pass
            return _err("VALIDATION_ERROR", "cursor is invalid")

    total = len(rows_sorted)
    page = rows_sorted[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        cobj = {"v": 1, "endpoint": endpoint, "offset": next_offset}
        next_cursor = base64.urlsafe_b64encode(json.dumps(cobj, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "categories": page,
        "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}
    }

    try:
        _audit("OK", None, {"account_id": account_id})
    except Exception:
        pass
    return resp

def get_due_items(now=None, project_id=None, category_id=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, base64, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0477000" if __import__("os").path.isdir("./environment_mix/0477000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_due_items"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _dt_parse_req(x, field):
        if x is None:
            return _now_utc(), None
        if not isinstance(x, str) or not x.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO date-time string", field=field)
        s = x.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO date-time string", field=field)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc), None

    def _dt_from_row(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            dt = v
        elif isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
        else:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _encode_cursor(i, account_id):
        raw = json.dumps({"v": 1, "ep": endpoint, "i": i, "a": account_id}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _decode_cursor(cur, account_id):
        if cur is None:
            return 0, None
        if not isinstance(cur, str) or not cur:
            return None, _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return None, _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        if not isinstance(obj, dict) or obj.get("v") != 1 or obj.get("ep") != endpoint or obj.get("a") != account_id:
            return None, _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        i = obj.get("i")
        if not isinstance(i, int) or i < 0:
            return None, _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        return i, None

    def _log(status_code, account_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "account_id": account_id,
            "status": status_code,
            "latency_ms": int(round((time.time() - t0) * 1000)),
            "timestamp": _iso(_now_utc()),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    account = None
    for st in ("active", "error", "revoked"):
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == st:
                account = a
                break
        if account:
            break
    if not account:
        e = _err("UNAUTHORIZED", "No authenticated account context available")
        _log("error", meta={"error": e["error"]})
        return e
    account_id = account.get("id")

    if project_id is not None and (not isinstance(project_id, str) or not project_id.strip()):
        e = _err("VALIDATION_ERROR", "project_id must be a string", field="project_id")
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e
    if category_id is not None and (not isinstance(category_id, str) or not category_id.strip()):
        e = _err("VALIDATION_ERROR", "category_id must be a string", field="category_id")
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        e = _err("VALIDATION_ERROR", "limit must be between 1 and 200", field="limit")
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e

    now_dt, e = _dt_parse_req(now, "now")
    if e:
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e

    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []

    rows = []
    for r in tasks:
        if not isinstance(r, dict):
            continue
        if r.get("account_id") != account_id:
            continue
        if r.get("status") != "active":
            continue
        if project_id is not None and r.get("project_id") != project_id:
            continue
        if category_id is not None and r.get("category_id") != category_id:
            continue
        dd = _dt_from_row(r.get("due_date"))
        if dd is None:
            continue
        if dd < now_dt:
            rows.append(r)

    # deterministic order: due_date asc, then updated_at desc
    def _k(r):
        dd = _dt_from_row(r.get("due_date")) or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc)
        ua = _dt_from_row(r.get("updated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return (dd, -int(ua.timestamp()), r.get("id") or "")
    rows.sort(key=_k)

    start_i, e = _decode_cursor(cursor, account_id)
    if e:
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e
    total = len(rows)
    page = rows[start_i:start_i + limit]
    next_i = start_i + len(page)
    has_more = next_i < total
    next_cursor = _encode_cursor(next_i, account_id) if has_more else None

    resp = {"tasks": page, "total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor, "now": _iso(now_dt)}
    _log("ok", account_id=account_id, meta={"returned": len(page), "total": total})
    return resp

def get_child_tasks(parent_id, recursive=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, base64, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0477000" if __import__("os").path.isdir("./environment_mix/0477000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_child_tasks"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None: return None
        if isinstance(dt, str): return dt
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(status_code, account_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "account_id": account_id,
            "status": status_code,
            "latency_ms": int(round((time.time() - t0) * 1000)),
            "timestamp": _iso(_now_utc()),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _encode_cursor(i, account_id):
        raw = json.dumps({"v": 1, "ep": endpoint, "i": i, "a": account_id}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _decode_cursor(cur, account_id):
        if cur is None:
            return 0, None
        if not isinstance(cur, str) or not cur:
            return None, _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return None, _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        if not isinstance(obj, dict) or obj.get("v") != 1 or obj.get("ep") != endpoint:
            return None, _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        if obj.get("a") != account_id:
            return None, _err("VALIDATION_ERROR", "cursor is invalid for this account context", field="cursor")
        i = obj.get("i")
        if not isinstance(i, int) or i < 0:
            return None, _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        return i, None

    # Validate inputs (relax parent_id format: accept any non-empty string; treat as id)
    if not isinstance(parent_id, str) or not parent_id.strip():
        e = _err("VALIDATION_ERROR", "parent_id is required and must be a non-empty string", field="parent_id")
        _log("error", meta={"error": e["error"]})
        return e
    if recursive is not None and not isinstance(recursive, bool):
        e = _err("VALIDATION_ERROR", "recursive must be a boolean", field="recursive")
        _log("error", meta={"error": e["error"]})
        return e
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")
        _log("error", meta={"error": e["error"]})
        return e

    # Ambient auth: pick any account that can satisfy the call (prefer active; fall back)
    accounts = _load("accounts.json")
    if not isinstance(accounts, list): accounts = []
    account = None
    for st in ("active", "error", "revoked"):
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == st:
                account = a
                break
        if account:
            break
    if not account:
        e = _err("UNAUTHORIZED", "No authenticated account context is available.")
        _log("error", meta={"error": e["error"]})
        return e
    account_id = account.get("id")

    # Cursor
    start_i, ce = _decode_cursor(cursor, account_id)
    if ce:
        _log("error", account_id=account_id, meta={"error": ce["error"]})
        return ce

    tasks = _load("tasks.json")
    if not isinstance(tasks, list): tasks = []
    cats = _load("categories.json")
    if not isinstance(cats, list): cats = []

    # Determine parent type by existence in this account; if not found, return empty list (not an error)
    parent_is_task = any(isinstance(t, dict) and t.get("id") == parent_id and t.get("account_id") == account_id for t in tasks)
    parent_is_cat = any(isinstance(c, dict) and c.get("id") == parent_id and c.get("account_id") == account_id for c in cats)
    if not parent_is_task and not parent_is_cat:
        resp = {"object": "list", "data": [], "total": 0, "has_more": False, "next_cursor": None}
        _log("ok", account_id=account_id, meta={"parent_id": parent_id, "recursive": bool(recursive), "returned": 0})
        return resp

    def _child_items_for(pid_task=None, pid_cat=None):
        out = []
        if pid_task is not None:
            for t in tasks:
                if not isinstance(t, dict): 
                    continue
                if t.get("account_id") != account_id:
                    continue
                if t.get("status") == "deleted":
                    continue
                if t.get("parent_task_id") == pid_task:
                    out.append({"kind": "task", "task": t})
        if pid_cat is not None:
            for c in cats:
                if not isinstance(c, dict):
                    continue
                if c.get("account_id") != account_id:
                    continue
                if c.get("status") == "deleted":
                    continue
                if c.get("parent_category_id") == pid_cat:
                    out.append({"kind": "category", "category": c})
            # also: tasks can belong to a project/category as a parent container; return tasks assigned to that project/category
            for t in tasks:
                if not isinstance(t, dict):
                    continue
                if t.get("account_id") != account_id:
                    continue
                if t.get("status") == "deleted":
                    continue
                if t.get("project_id") == pid_cat or t.get("category_id") == pid_cat:
                    out.append({"kind": "task", "task": t})
        return out

    # Depth-first descendants with hard cap
    hard_cap = 5000
    items = []
    seen_task_ids = set()
    seen_cat_ids = set()

    def _push_children_task(tid):
        nonlocal items
        for it in _child_items_for(pid_task=tid):
            if it["kind"] == "task":
                tid2 = it["task"].get("id")
                if tid2 in seen_task_ids:
                    continue
                seen_task_ids.add(tid2)
            items.append(it)
            if len(items) >= hard_cap:
                return False
        return True

    def _push_children_cat(cid):
        nonlocal items
        for it in _child_items_for(pid_cat=cid):
            if it["kind"] == "task":
                tid2 = it["task"].get("id")
                if tid2 in seen_task_ids:
                    continue
                seen_task_ids.add(tid2)
            else:
                cid2 = it["category"].get("id")
                if cid2 in seen_cat_ids:
                    continue
                seen_cat_ids.add(cid2)
            items.append(it)
            if len(items) >= hard_cap:
                return False
        return True

    rec = bool(recursive)
    if not rec:
        items = _child_items_for(pid_task=parent_id if parent_is_task else None, pid_cat=parent_id if parent_is_cat else None)
    else:
        stack = []
        if parent_is_task:
            stack.append(("task", parent_id))
        if parent_is_cat:
            stack.append(("cat", parent_id))
        while stack and len(items) < hard_cap:
            kind, pid = stack.pop()
            if kind == "task":
                children = _child_items_for(pid_task=pid)
            else:
                children = _child_items_for(pid_cat=pid)

            # depth-first: push in reverse to preserve some stable order
            for it in reversed(children):
                if len(items) >= hard_cap:
                    break
                if it["kind"] == "task":
                    tid2 = it["task"].get("id")
                    if tid2 in seen_task_ids:
                        continue
                    seen_task_ids.add(tid2)
                    items.append(it)
                    stack.append(("task", tid2))
                else:
                    cid2 = it["category"].get("id")
                    if cid2 in seen_cat_ids:
                        continue
                    seen_cat_ids.add(cid2)
                    items.append(it)
                    stack.append(("cat", cid2))

    total = len(items)
    if start_i > total:
        start_i = total

    page = items[start_i:start_i + limit]
    next_i = start_i + len(page)
    has_more = next_i < total
    next_cursor = _encode_cursor(next_i, account_id) if has_more else None

    resp = {"object": "list", "data": page, "total": total, "has_more": has_more, "next_cursor": next_cursor}
    _log("ok", account_id=account_id, meta={"parent_id": parent_id, "recursive": rec, "returned": len(page), "total": total})
    return resp

