    def _decode_cursor(cur, account_id):
        if cur is None:
            return 0, None
        if not isinstance(cur, str) or not cur:
            return None, _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return None, _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        if not isinstance(obj, dict) or obj.get("v") != 1 or obj.get("ep") != endpoint:
            return None, _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        if obj.get("a") != account_id:
            return None, _err("VALIDATION_ERROR", "cursor is invalid for this account context", field="cursor")
        i = obj.get("i")
        if not isinstance(i, int) or i < 0:
            return None, _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        return i, None

    def _dt_from_row(v):
        if v is None: return None
        if isinstance(v, datetime.datetime):
            dt = v
        elif isinstance(v, str):
            s = v.strip()
            if not s: return None
            if s.endswith("Z"): s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
        else:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _parse_date_field(x, field):
        if x is None:
            return None, None
        if not isinstance(x, str) or not x.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be YYYY-MM-DD", field=field)
        s = x.strip()
        # accept date-time strings by extracting date portion if ISO-like
        if re.match(r"^\d{4}-\d{2}-\d{2}$", s):
            return s, None
        m = re.match(r"^(\d{4}-\d{2}-\d{2})[T ].*$", s)
        if m:
            return m.group(1), None
        return None, _err("VALIDATION_ERROR", f"{field} must be YYYY-MM-DD", field=field)

    # Validate limit
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
