def test_api_connection(**_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0477000" if __import__("os").path.isdir("./environment_mix/0477000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    # No explicit credentials in parameters; resolve a usable authenticated context from store.
    started = datetime.datetime.utcnow()
    try:
        accounts = _load("accounts.json")
        now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

        # "Validate upstream credentials" cannot be performed offline. Real behavior: succeed only if active account exists.
        # If none active, mark an account error if any account exists (pick most recently updated), else unauthorized.
        active = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active"]
        if active:
            # Succeed; also set last_successful_sync_at to now to reflect connection check.
            # Pick the most recently updated active
            def _dt(v):
                if not v:
                    return None
                try:
                    return datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
                except Exception:
                    return None

            active.sort(key=lambda r: (_dt(r.get("updated_at")) or datetime.datetime.min), reverse=True)
            acct = active[0]
            acct["last_successful_sync_at"] = now_iso
            acct["updated_at"] = now_iso
            _save("accounts.json", accounts)

            return {
                "status": "OK",
                "account": {
                    "id": acct.get("id"),
                    "am_user_id": acct.get("am_user_id"),
                    "email": acct.get("email"),
                    "display_name": acct.get("display_name"),
                    "timezone": acct.get("timezone"),
                    "status": acct.get("status"),
                    "last_successful_sync_at": acct.get("last_successful_sync_at"),
                },
                "checked_at": now_iso,
                "latency_ms": int((datetime.datetime.utcnow() - started).total_seconds() * 1000),
            }

        # No active account available; set error on an existing account if possible.
        if accounts:
            # Choose most recently updated; if none parseable, take first.
            def _dt(v):
                if not v:
                    return None
                try:
                    return datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
                except Exception:
                    return None

            accounts_sorted = list(accounts)
            accounts_sorted.sort(
                key=lambda r: (_dt(r.get("updated_at")) or datetime.datetime.min) if isinstance(r, dict) else datetime.datetime.min,
                reverse=True,
            )
            acct = accounts_sorted[0]
            # Apply lifecycle transition to error if allowed (active/error -> error, revoked cannot transition)
            if isinstance(acct, dict):
                if acct.get("status") in ("active", "error"):
                    acct["status"] = "error"
                # if revoked, keep revoked but still record error details
                acct["last_error_code"] = "NO_ACTIVE_ACCOUNT"
                acct["last_error_message"] = "No active account connection found to validate credentials."
                acct["updated_at"] = now_iso
                _save("accounts.json", accounts)

            return _err(
                "UNAUTHORIZED",
                "No active account connection is available for this request.",
                details={"last_error_code": "NO_ACTIVE_ACCOUNT"},
            )

        return _err(
            "UNAUTHORIZED",
            "No account connection exists in datastore.",
            details={"last_error_code": "NO_ACCOUNT"},
        )
    except Exception as e:
        return _err("VALIDATION_ERROR", "Unexpected server error.", details={"exception": str(e)})

def start_time_tracking(task_id, started_at=None, note=None, **_extra):
    import json, os, datetime, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0477000" if __import__("os").path.isdir("./environment_mix/0477000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _iso(dt):
        if dt.tzinfo is not None:
            dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _gen_ulid(prefix):
        # Simple ULID-like generator (not strictly ULID spec) using Crockford base32 time+random.
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        import random

        ms = int(datetime.datetime.utcnow().timestamp() * 1000)
        # 10 chars time (50 bits) + 16 chars randomness (80 bits) -> 26 chars; we keep >=10 after prefix requirement.
        def enc(n, length):
            out = []
            for _ in range(length):
                out.append(alphabet[n % 32])
                n //= 32
            return "".join(reversed(out))

        time_part = enc(ms, 10)
        rand_part = "".join(random.choice(alphabet) for _ in range(16))
        return f"{prefix}{time_part}{rand_part}"

    # Validate inputs
    if not isinstance(task_id, str) or not re.match(r"^am_tsk_[0-9A-HJKMNP-TV-Z]{10,}$", task_id):
        return _err("VALIDATION_ERROR", "task_id is malformed.")
    if started_at is not None and _parse_dt(started_at) is None:
        return _err("VALIDATION_ERROR", "started_at is not a valid ISO 8601 datetime.")
    if note is not None and not isinstance(note, str):
        return _err("VALIDATION_ERROR", "note must be a string when provided.")

    started_dt = _parse_dt(started_at) if started_at is not None else datetime.datetime.utcnow()

    try:
        accounts = _load("accounts.json")
        tasks = _load("tasks.json")
        sessions = _load("time_tracking.json")

        # Resolve authenticated account context: choose an active account that owns the task_id.
        task_row = None
        for t in tasks:
            if isinstance(t, dict) and t.get("id") == task_id:
                task_row = t
                break
        if not task_row:
            return _err("NOT_FOUND", "Task not found.")

        account_id = task_row.get("account_id")
        acct = None
        for a in accounts:
            if isinstance(a, dict) and a.get("id") == account_id:
                acct = a
                break
        if not acct or acct.get("status") != "active":
            return _err("UNAUTHORIZED", "No active account context available for this task.")

        if task_row.get("status") == "deleted":
            return _err("NOT_FOUND", "Task not found.")  # treat deleted as not found for start

        # Enforce at most one running session per account
        running = None
        for s in sessions:
            if isinstance(s, dict) and s.get("account_id") == account_id and s.get("status") == "running":
                running = s
                break
        if running:
            return _err("CONFLICT", "A time tracking session is already running for this account.", running_session_id=running.get("id"))

        now_iso = _now_iso()
        session = {
            "id": _gen_ulid("am_tt_"),
            "account_id": account_id,
            "task_id": task_id,
            "am_time_track_id": None,
            "status": "running",
            "started_at": _iso(started_dt),
            "stopped_at": None,
            "duration_seconds": None,
            "note": note,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        sessions.append(session)
        _save("time_tracking.json", sessions)

        return {"time_track": session}
    except Exception as e:
        return _err("VALIDATION_ERROR", "Unexpected server error.", details={"exception": str(e)})

def stop_time_tracking(task_id, stopped_at=None, **_extra):
    import json, os, datetime, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0477000" if __import__("os").path.isdir("./environment_mix/0477000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _iso(dt):
        if dt.tzinfo is not None:
            dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _dt(s):
        if not s:
            return None
        try:
            return datetime.datetime.fromisoformat(str(s).replace("Z", "+00:00"))
        except Exception:
            return None

    if not isinstance(task_id, str) or not re.match(r"^am_tsk_[0-9A-HJKMNP-TV-Z]{10,}$", task_id):
        return _err("VALIDATION_ERROR", "task_id is malformed.")
    if stopped_at is not None and _parse_dt(stopped_at) is None:
        return _err("VALIDATION_ERROR", "stopped_at is not a valid ISO 8601 datetime.")

    stop_dt = _parse_dt(stopped_at) if stopped_at is not None else datetime.datetime.utcnow()

    try:
        accounts = _load("accounts.json")
        tasks = _load("tasks.json")
        sessions = _load("time_tracking.json")

        # Task must exist (even if deleted rule says status!='deleted' for start; stop requires task exists per tool text)
        task_row = None
        for t in tasks:
            if isinstance(t, dict) and t.get("id") == task_id:
                task_row = t
                break
        if not task_row or task_row.get("status") == "deleted":
            return _err("NOT_FOUND", "Task not found.")

        account_id = task_row.get("account_id")
        acct = None
        for a in accounts:
            if isinstance(a, dict) and a.get("id") == account_id:
                acct = a
                break
        if not acct or acct.get("status") != "active":
            return _err("UNAUTHORIZED", "No active account context available for this task.")

        # Find running session for this account
        running = None
        for s in sessions:
            if isinstance(s, dict) and s.get("account_id") == account_id and s.get("status") == "running":
                running = s
                break
        if not running:
            return _err("NOT_FOUND", "No running time tracking session found to stop.")

        # If task_id provided must match the running session's task_id
        if running.get("task_id") != task_id:
            return _err("NOT_FOUND", "No matching running session found for the provided task_id.")

        started_dt = _dt(running.get("started_at"))
        if not started_dt:
            return _err("VALIDATION_ERROR", "Corrupt session: started_at is invalid.")
        if stop_dt.tzinfo is not None:
            stop_dt_utc = stop_dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
        else:
            stop_dt_utc = stop_dt
        # Enforce started_at <= stopped_at
        if stop_dt_utc < (started_dt.astimezone(datetime.timezone.utc).replace(tzinfo=None) if started_dt.tzinfo else started_dt):
            return _err("VALIDATION_ERROR", "stopped_at must be after started_at.")

        duration = int(round((stop_dt_utc - (started_dt.astimezone(datetime.timezone.utc).replace(tzinfo=None) if started_dt.tzinfo else started_dt)).total_seconds()))
        if duration < 0:
            duration = 0

        now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        running["status"] = "stopped"
        running["stopped_at"] = _iso(stop_dt)
        running["duration_seconds"] = duration
        running["updated_at"] = now_iso

        _save("time_tracking.json", sessions)
        return {"time_track": running}
    except Exception as e:
        return _err("VALIDATION_ERROR", "Unexpected server error.", details={"exception": str(e)})

def get_time_tracks(task_ids=None, from_=None, to=None, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, base64, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0477000" if __import__("os").path.isdir("./environment_mix/0477000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_time_tracks"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None: return None
        if isinstance(dt, str): return dt
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _dt_parse_req(x, field):
        if x is None:
            return None, None
        if not isinstance(x, str) or not x.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO 8601 datetime", field=field)
        s = x.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO 8601 datetime", field=field)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc), None

    def _dt_from_row(v):
        if v is None: return None
        if isinstance(v, datetime.datetime):
            dt = v
        elif isinstance(v, str):
            s = v.strip()
            if not s: return None
            if s.endswith("Z"): s = s[:-1] + "+00:00"
            try: dt = datetime.datetime.fromisoformat(s)
            except ValueError: return None
        else:
            return None
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _encode_cursor(i, account_id):
        raw = json.dumps({"v": 1, "ep": endpoint, "i": i, "a": account_id}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _decode_cursor(cur, account_id):
        if cur is None:
            return 0, None
        if not isinstance(cur, str) or not cur:
            return None, _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return None, _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        if not isinstance(obj, dict) or obj.get("v") != 1 or obj.get("ep") != endpoint or obj.get("a") != account_id:
            return None, _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        i = obj.get("i")
        if not isinstance(i, int) or i < 0:
            return None, _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        return i, None

    def _log(status_code, account_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "account_id": account_id,
            "status": status_code,
            "latency_ms": int(round((time.time() - t0) * 1000)),
            "timestamp": _iso(_now_utc()),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    account = None
    for st in ("active", "error", "revoked"):
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == st:
                account = a
                break
        if account:
            break
    if not account:
        e = _err("UNAUTHORIZED", "No authenticated account context available")
        _log("error", meta={"error": e["error"]})
        return e
    account_id = account.get("id")

    # Validate params
    if task_ids is not None:
        if not isinstance(task_ids, list):
            e = _err("VALIDATION_ERROR", "task_ids must be an array of strings", field="task_ids")
            _log("error", account_id=account_id, meta={"error": e["error"]})
            return e
        for tid in task_ids:
            if not isinstance(tid, str) or not tid.strip():
                e = _err("VALIDATION_ERROR", "task_ids must be an array of strings", field="task_ids")
                _log("error", account_id=account_id, meta={"error": e["error"]})
                return e
        task_ids_set = set([t.strip() for t in task_ids])
    else:
        task_ids_set = None

    from_dt, e = _dt_parse_req(from_, "from")
    if e:
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e
    to_dt, e = _dt_parse_req(to, "to")
    if e:
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e
    if from_dt is not None and to_dt is not None and from_dt > to_dt:
        e = _err("VALIDATION_ERROR", "`from` must be before or equal to `to`", field="from")
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e

    if status is not None:
        if not isinstance(status, str) or status not in {"running", "stopped", "deleted"}:
            e = _err("VALIDATION_ERROR", "status is invalid", field="status")
            _log("error", account_id=account_id, meta={"error": e["error"]})
            return e

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        e = _err("VALIDATION_ERROR", "limit must be between 1 and 200", field="limit")
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e

    if sort is None:
        sort = "-started_at"
    if not isinstance(sort, str) or sort not in {"started_at", "-started_at", "stopped_at", "-stopped_at", "created_at", "-created_at"}:
        e = _err("VALIDATION_ERROR", "sort is invalid", field="sort")
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e

    tracks = _load("time_tracking.json")
    if not isinstance(tracks, list):
        tracks = []

    # Business rule: only return running/stopped (exclude deleted) unless explicitly asked for deleted
    allowed = {"running", "stopped"} if status is None else {status}

    rows = []
    for r in tracks:
        if not isinstance(r, dict):
            continue
        if r.get("account_id") != account_id:
            continue
        st = r.get("status")
        if st not in allowed:
            continue
        if status is None and st == "deleted":
            continue
        if task_ids_set is not None and r.get("task_id") not in task_ids_set:
            continue
        sa = _dt_from_row(r.get("started_at"))
        ea = _dt_from_row(r.get("stopped_at")) if r.get("stopped_at") is not None else None
        # filter range against started_at (inclusive) and stopped_at (exclusive when available)
        if from_dt is not None:
            ref = sa or ea
            if ref is None or ref < from_dt:
                continue
        if to_dt is not None:
            ref = sa or ea
            if ref is None or ref >= to_dt:
                continue
        rows.append(r)

    field = sort.lstrip("-")
    desc = sort.startswith("-")

    def _key(r):
        v = _dt_from_row(r.get(field))
        if v is None:
            v = datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return (v, r.get("id") or "")
    rows.sort(key=_key, reverse=desc)

    start_i, e = _decode_cursor(cursor, account_id)
    if e:
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e
    total = len(rows)
    page = rows[start_i:start_i + limit]
    next_i = start_i + len(page)
    has_more = next_i < total
    next_cursor = _encode_cursor(next_i, account_id) if has_more else None

    resp = {"time_tracks": page, "total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}
    _log("ok", account_id=account_id, meta={"returned": len(page), "total": total})
    return resp

def claim_reward_points(task_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0477000" if __import__("os").path.isdir("./environment_mix/0477000") else "/app/database")
    def _load(n):
