            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _log(endpoint, credential_id, status, started):
        latency_ms = int(round((time.time() - started) * 1000))
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
            "ts": _now_iso(),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": latency_ms
        })
        _save("request_logs.json", logs)

    def _check_limits(endpoint, credential_id):
        # If no request_logs/quota config exists, do not enforce.
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.now(datetime.timezone.utc)
        window_s = 60
        max_per_min = 120
        recent = 0
        for r in reversed(logs[-5000:]):
            if r.get("endpoint") != endpoint:
                continue
            if credential_id is not None and r.get("credential_id") != credential_id:
                continue
            ts = _parse_dt(r.get("ts"))
            if not ts:
                continue
            if (now - ts).total_seconds() <= window_s:
                recent += 1
        if recent >= max_per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    started = time.time()
    endpoint = "claim_reward_points"
    credential_id = None

    # Validate input
    if not isinstance(task_id, str) or not re.match(r"^am_tsk_[0-9A-HJKMNP-TV-Z]{10,}$", task_id):
        _log(endpoint, credential_id, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "task_id is malformed.", field="task_id")

    # Auth context: pick an account that actually owns this task and is usable.
    accounts = _load("accounts.json")
    tasks = _load("tasks.json")
    if not isinstance(accounts, list):
        accounts = []
    if not isinstance(tasks, list):
        tasks = []

    task = None
    for t in tasks:
        if t.get("id") == task_id:
            task = t
            break
    if task is None:
        _log(endpoint, credential_id, "NOT_FOUND", started)
        return _err("NOT_FOUND", "Task not found.", task_id=task_id)

    account_id = task.get("account_id")
    acct = None
    for a in accounts:
        if a.get("id") == account_id:
            acct = a
            break
    if acct is None:
        _log(endpoint, credential_id, "UNAUTHORIZED", started)
        return _err("UNAUTHORIZED", "No authorized account context available for this operation.")

    # Rate limit (per account context)
    credential_id = acct.get("id")
    lim = _check_limits(endpoint, credential_id)
    if lim:
        _log(endpoint, credential_id, lim["error"]["code"], started)
        return lim

    # Validate eligibility
    if task.get("status") == "deleted":
        _log(endpoint, credential_id, "NOT_FOUND", started)
        return _err("NOT_FOUND", "Task not found.", task_id=task_id)

    if task.get("status") != "done":
        _log(endpoint, credential_id, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "Task is not eligible for reward points because it is not completed.", task_id=task_id)

    if task.get("reward_points_claimed") is True:
        _log(endpoint, credential_id, "CONFLICT", started)
        return _err("CONFLICT", "Reward points have already been claimed for this task.", task_id=task_id)

    # Mutate
    now_iso = _now_iso()
    task["reward_points_claimed"] = True
    task["reward_points_claimed_at"] = now_iso
    task["updated_at"] = now_iso

    # Persist
    _save("tasks.json", tasks)

    resp = {
        "task": task,
        "reward": {
            "claimed": True,
            "claimed_at": now_iso
        }
    }
    _log(endpoint, credential_id, "OK", started)
    return resp

