            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _log(endpoint, credential_id, status, started):
        latency_ms = int(round((time.time() - started) * 1000))
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
            "ts": _now_iso(),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": latency_ms
        })
        _save("request_logs.json", logs)

    def _check_limits(endpoint, credential_id):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.now(datetime.timezone.utc)
        window_s = 60
        max_per_min = 120
        recent = 0
        for r in reversed(logs[-5000:]):
            if r.get("endpoint") != endpoint:
                continue
            if credential_id is not None and r.get("credential_id") != credential_id:
                continue
            ts = _parse_dt(r.get("ts"))
            if not ts:
                continue
            if (now - ts).total_seconds() <= window_s:
                recent += 1
        if recent >= max_per_min:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    def _gen_ulid_like(prefix):
        # Not a real ULID, but matches vendor pattern constraints.
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return f"{prefix}{''.join(random.choice(alphabet) for _ in range(16))}"

    started = time.time()
    endpoint = "create_project"

    # Validate inputs
    if not isinstance(title, str) or not title.strip():
        _log(endpoint, None, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "title is required and must be non-empty.", field="title")
    if parent_category_id is not None:
        if not isinstance(parent_category_id, str) or not re.match(r"^am_cat_[0-9A-HJKMNP-TV-Z]{10,}$", parent_category_id):
            _log(endpoint, None, "VALIDATION_ERROR", started)
            return _err("VALIDATION_ERROR", "parent_category_id is malformed.", field="parent_category_id")
    if color is not None and not isinstance(color, str):
        _log(endpoint, None, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "color must be a string.", field="color")
    if archived is not None and not isinstance(archived, bool):
        _log(endpoint, None, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "archived must be a boolean.", field="archived")

    # Ambient auth: pick an active account (must be able to create)
    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = None
    for a in accounts:
        if a.get("status") == "active":
            acct = a
            break
    if acct is None:
        _log(endpoint, None, "UNAUTHORIZED", started)
        return _err("UNAUTHORIZED", "No authorized account context available for this operation.")
    credential_id = acct.get("id")

    lim = _check_limits(endpoint, credential_id)
    if lim:
        _log(endpoint, credential_id, lim["error"]["code"], started)
        return lim

    categories = _load("categories.json")
    if not isinstance(categories, list):
        categories = []

    parent_row = None
    if parent_category_id is not None:
        for c in categories:
            if c.get("id") == parent_category_id and c.get("account_id") == acct.get("id"):
                parent_row = c
                break
        if parent_row is None or parent_row.get("status") == "deleted":
            _log(endpoint, credential_id, "NOT_FOUND", started)
            return _err("NOT_FOUND", "parent_category_id not found.", parent_category_id=parent_category_id)
        if parent_row.get("status") == "archived":
            _log(endpoint, credential_id, "CONFLICT", started)
            return _err("CONFLICT", "Parent category is archived and cannot accept new children.", parent_category_id=parent_category_id)

    now_iso = _now_iso()
    new_id = _gen_ulid_like("am_cat_")
    # Ensure uniqueness
    existing_ids = {c.get("id") for c in categories if isinstance(c, dict)}
    tries = 0
    while new_id in existing_ids and tries < 10:
        new_id = _gen_ulid_like("am_cat_")
        tries += 1
    if new_id in existing_ids:
        _log(endpoint, credential_id, "CONFLICT", started)
        return _err("CONFLICT", "Could not generate a unique id for the project.")

    # am_category_id must be unique per (account_id, am_category_id); use same as id in this local store.
    am_category_id = new_id
    for c in categories:
        if c.get("account_id") == acct.get("id") and c.get("am_category_id") == am_category_id:
            _log(endpoint, credential_id, "CONFLICT", started)
            return _err("CONFLICT", "Project already exists with this upstream category id.")

    is_archived = bool(archived) if archived is not None else False
    status = "archived" if is_archived else "active"

    row = {
        "id": new_id,
        "account_id": acct.get("id"),
        "am_category_id": am_category_id,
        "title": title.strip(),
        "type": "project",
        "parent_category_id": parent_category_id,
        "color": color,
        "archived": is_archived,
        "status": status,
        "created_at": now_iso,
        "updated_at": now_iso
    }

    # Constraint: archived=true implies status='archived' (already)
    categories.append(row)
    _save("categories.json", categories)

    _log(endpoint, credential_id, "OK", started)
    return {"project": row}

