    if lim:
        _log(endpoint, credential_id, lim["error"]["code"], started)
        return lim

    categories = _load("categories.json")
    tasks_store = _load("tasks.json")
    if not isinstance(categories, list):
        categories = []
    if not isinstance(tasks_store, list):
        tasks_store = []

    # Resolve parent category if provided
    parent_row = None
    if parent_category_id is not None:
        for c in categories:
            if c.get("id") == parent_category_id and c.get("account_id") == acct.get("id"):
                parent_row = c
                break
        if parent_row is None or parent_row.get("status") == "deleted":
            _log(endpoint, credential_id, "NOT_FOUND", started)
            return _err("NOT_FOUND", "project.parent_category_id not found.", parent_category_id=parent_category_id)
        if parent_row.get("status") == "archived":
            _log(endpoint, credential_id, "CONFLICT", started)
            return _err("CONFLICT", "Parent category is archived and cannot accept new children.", parent_category_id=parent_category_id)

    # Pre-validate tasks (atomic operation)
    if len(tasks) > 200:
        _log(endpoint, credential_id, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "A maximum of 200 tasks can be created per request.", field="tasks")

    # Build indexes for FK validation
    cat_by_id = {c.get("id"): c for c in categories if isinstance(c, dict) and c.get("account_id") == acct.get("id")}
    task_by_id = {t.get("id"): t for t in tasks_store if isinstance(t, dict) and t.get("account_id") == acct.get("id")}

    # Account timezone offset default
    default_off = acct.get("default_timezone_offset_minutes")
    if not isinstance(default_off, int) or default_off < -840 or default_off > 840:
        default_off = 0

    prepared_tasks = []
    for idx, t in enumerate(tasks):
        if not isinstance(t, dict):
            _log(endpoint, credential_id, "VALIDATION_ERROR", started)
            return _err("VALIDATION_ERROR", "Each task must be an object.", index=idx)
        ttl = t.get("title")
        if not isinstance(ttl, str) or not ttl.strip() or len(ttl.strip()) > 500:
            _log(endpoint, credential_id, "VALIDATION_ERROR", started)
            return _err("VALIDATION_ERROR", "Task title is required and must be 1..500 chars.", index=idx, field=f"tasks[{idx}].title")

        note = t.get("note")
        if note is not None and not isinstance(note, str):
            _log(endpoint, credential_id, "VALIDATION_ERROR", started)
            return _err("VALIDATION_ERROR", "note must be a string.", index=idx, field=f"tasks[{idx}].note")

        category_id = t.get("category_id")
        if category_id is not None:
            if not isinstance(category_id, str) or not re.match(r"^am_cat_[0-9A-HJKMNP-TV-Z]{10,}$", category_id):
                _log(endpoint, credential_id, "VALIDATION_ERROR", started)
                return _err("VALIDATION_ERROR", "category_id is malformed.", index=idx, field=f"tasks[{idx}].category_id")
            cat = cat_by_id.get(category_id)
            if cat is None or cat.get("status") == "deleted":
                _log(endpoint, credential_id, "NOT_FOUND", started)
                return _err("NOT_FOUND", "category_id not found.", index=idx, category_id=category_id)
        parent_task_id = t.get("parent_task_id")
        if parent_task_id is not None:
            if not isinstance(parent_task_id, str) or not re.match(r"^am_tsk_[0-9A-HJKMNP-TV-Z]{10,}$", parent_task_id):
                _log(endpoint, credential_id, "VALIDATION_ERROR", started)
                return _err("VALIDATION_ERROR", "parent_task_id is malformed.", index=idx, field=f"tasks[{idx}].parent_task_id")
            pt = task_by_id.get(parent_task_id)
            if pt is None or pt.get("status") == "deleted":
                _log(endpoint, credential_id, "NOT_FOUND", started)
                return _err("NOT_FOUND", "parent_task_id not found.", index=idx, parent_task_id=parent_task_id)

        prio = t.get("priority")
        if prio is not None:
            if not isinstance(prio, int) or prio not in (1, 2, 3, 4, 5):
                _log(endpoint, credential_id, "VALIDATION_ERROR", started)
                return _err("VALIDATION_ERROR", "priority must be one of 1..5.", index=idx, field=f"tasks[{idx}].priority")

        due = t.get("due_date")
        sched = t.get("scheduled_for")
        due_iso, due_err = _normalize_due_or_sched(due, default_off)
        if due_err:
            _log(endpoint, credential_id, "VALIDATION_ERROR", started)
            return _err("VALIDATION_ERROR", "due_date must be ISO 8601 date-time or YYYY-MM-DD.", index=idx, field=f"tasks[{idx}].due_date")
        sched_iso, sched_err = _normalize_due_or_sched(sched, default_off)
        if sched_err:
            _log(endpoint, credential_id, "VALIDATION_ERROR", started)
            return _err("VALIDATION_ERROR", "scheduled_for must be ISO 8601 date-time or YYYY-MM-DD.", index=idx, field=f"tasks[{idx}].scheduled_for")

        prepared_tasks.append({
            "title": ttl.strip(),
            "note": note,
            "category_id": category_id,
            "parent_task_id": parent_task_id,
            "due_date": due_iso,
            "scheduled_for": sched_iso,
            "priority": prio
        })

    # All validation passed: create project + tasks
    now_iso = _now_iso()

    # Create project id
    existing_cat_ids = {c.get("id") for c in categories if isinstance(c, dict)}
    proj_id = _gen_id("am_cat_")
    tries = 0
    while proj_id in existing_cat_ids and tries < 10:
        proj_id = _gen_id("am_cat_")
        tries += 1
    if proj_id in existing_cat_ids:
        _log(endpoint, credential_id, "CONFLICT", started)
        return _err("CONFLICT", "Could not generate a unique id for the project.")

    proj_row = {
        "id": proj_id,
        "account_id": acct.get("id"),
        "am_category_id": proj_id,
        "title": title.strip(),
        "type": "project",
        "parent_category_id": parent_category_id,
        "color": color,
        "archived": bool(archived) if archived is not None else False,
        "status": "archived" if (bool(archived) if archived is not None else False) else "active",
        "created_at": now_iso,
        "updated_at": now_iso
    }

    # Create tasks under project
    existing_task_ids = {t.get("id") for t in tasks_store if isinstance(t, dict)}
    created_tasks = []
    for pt in prepared_tasks:
        tid = _gen_id("am_tsk_")
        tries = 0
        while tid in existing_task_ids and tries < 10:
            tid = _gen_id("am_tsk_")
            tries += 1
        if tid in existing_task_ids:
            _log(endpoint, credential_id, "CONFLICT", started)
            return _err("CONFLICT", "Could not generate a unique id for a task.")
        existing_task_ids.add(tid)

        task_row = {
            "id": tid,
            "account_id": acct.get("id"),
            "am_item_id": tid,
            "title": pt["title"],
            "note": pt["note"],
            "project_id": proj_id,
            "category_id": pt["category_id"],
            "parent_task_id": pt["parent_task_id"],
            "due_date": pt["due_date"],
            "scheduled_for": pt["scheduled_for"],
            "priority": pt["priority"],
            "status": "active",
            "completed_at": None,
            "completion_timezone_offset_minutes": None,
            "reward_points_claimed": False,
            "reward_points_claimed_at": None,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        created_tasks.append(task_row)

    # Persist atomically (single write phase)
    categories.append(proj_row)
    tasks_store.extend(created_tasks)
    _save("categories.json", categories)
    _save("tasks.json", tasks_store)

    _log(endpoint, credential_id, "OK", started)
    return {"project": proj_row, "tasks": created_tasks}

def get_project_overview(project_id=None, include_archived=None, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, base64, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0477000" if __import__("os").path.isdir("./environment_mix/0477000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_project_overview"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None: return None
        if isinstance(dt, str): return dt
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _dt_from_row(v):
        if v is None: return None
        if isinstance(v, datetime.datetime):
            dt = v
        elif isinstance(v, str):
            s = v.strip()
            if not s: return None
            if s.endswith("Z"): s = s[:-1] + "+00:00"
            try: dt = datetime.datetime.fromisoformat(s)
            except ValueError: return None
        else:
            return None
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _log(status_code, account_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "account_id": account_id,
            "status": status_code,
            "latency_ms": int(round((time.time() - t0) * 1000)),
            "timestamp": _iso(_now_utc()),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _encode_cursor(i, account_id):
        raw = json.dumps({"v": 1, "ep": endpoint, "i": i, "a": account_id}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _decode_cursor(cur, account_id):
        if cur is None:
            return 0, None
        if not isinstance(cur, str) or not cur:
            return None, _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return None, _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        if not isinstance(obj, dict) or obj.get("v") != 1 or obj.get("ep") != endpoint:
            return None, _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        if obj.get("a") != account_id:
            return None, _err("VALIDATION_ERROR", "cursor is invalid for this account context", field="cursor")
        i = obj.get("i")
        if not isinstance(i, int) or i < 0:
            return None, _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        return i, None

    # Validate params
    if include_archived is not None and not isinstance(include_archived, bool):
        e = _err("VALIDATION_ERROR", "include_archived must be a boolean", field="include_archived")
        _log("error", meta={"error": e["error"]})
        return e
    if status is not None and status not in ("active", "archived", "deleted"):
        e = _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted", field="status")
        _log("error", meta={"error": e["error"]})
        return e
    if sort is None:
        sort = "updated_at"
    if sort not in ("created_at", "updated_at", "title"):
        e = _err("VALIDATION_ERROR", "sort must be one of: created_at, updated_at, title", field="sort")
        _log("error", meta={"error": e["error"]})
        return e
    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        e = _err("VALIDATION_ERROR", "order must be 'asc' or 'desc'", field="order")
        _log("error", meta={"error": e["error"]})
        return e
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")
        _log("error", meta={"error": e["error"]})
        return e
    if project_id is not None:
        # relax: accept any non-empty string, but if it doesn't look like am_cat_..., treat as validation error per tool contract
        if not isinstance(project_id, str) or not re.match(r"^am_cat_[0-9A-Z]{10,}$", project_id):
            e = _err("VALIDATION_ERROR", "project_id is malformed", field="project_id")
            _log("error", meta={"error": e["error"]})
            return e

    # Ambient auth
    accounts = _load("accounts.json")
    if not isinstance(accounts, list): accounts = []
    account = None
    for st in ("active", "error", "revoked"):
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == st:
                account = a
                break
        if account:
            break
    if not account:
        e = _err("UNAUTHORIZED", "No authenticated account context is available.")
        _log("error", meta={"error": e["error"]})
        return e
    account_id = account.get("id")

    cats = _load("categories.json")
    if not isinstance(cats, list): cats = []
    tasks = _load("tasks.json")
    if not isinstance(tasks, list): tasks = []

    # Single-project mode
    if project_id is not None:
        proj = None
        for c in cats:
            if isinstance(c, dict) and c.get("id") == project_id and c.get("account_id") == account_id:
                proj = c
                break
        if not proj or proj.get("status") == "deleted":
            e = _err("NOT_FOUND", "Project not found", project_id=project_id)
            _log("error", account_id=account_id, meta={"error": e["error"]})
            return e

        if proj.get("type") != "project":
            e = _err("CONFLICT", "category exists but is not a project", project_id=project_id, type=proj.get("type"))
            _log("error", account_id=account_id, meta={"error": e["error"]})
            return e

        now = _now_utc()
        active_count = 0
        done_count = 0
        overdue_count = 0
        for t in tasks:
            if not isinstance(t, dict): 
                continue
            if t.get("account_id") != account_id:
                continue
            if t.get("project_id") != project_id:
                continue
            st = t.get("status")
            if st == "active":
                active_count += 1
                dd = _dt_from_row(t.get("due_date"))
                if dd is not None and dd < now:
                    overdue_count += 1
            elif st == "done":
                done_count += 1

        resp = {
            "object": "project_overview",
            "project": proj,
            "counts": {"active": active_count, "done": done_count, "overdue": overdue_count}
        }
        _log("ok", account_id=account_id, meta={"mode": "single", "project_id": project_id})
        return resp

    # List mode
    start_i, ce = _decode_cursor(cursor, account_id)
    if ce:
        _log("error", account_id=account_id, meta={"error": ce["error"]})
        return ce

    inc_arch = True if include_archived is None else include_archived

    prows = []
    for c in cats:
        if not isinstance(c, dict):
            continue
        if c.get("account_id") != account_id:
            continue
        if c.get("type") != "project":
            continue
        if c.get("status") == "deleted":
            continue
        if not inc_arch and (c.get("status") == "archived" or c.get("archived") is True):
            continue
        if status is not None and c.get("status") != status:
            continue
        prows.append(c)

    def _sort_key(c):
        if sort == "title":
            return (c.get("title") or "").lower()
        if sort == "created_at":
            return _dt_from_row(c.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return _dt_from_row(c.get("updated_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    prows.sort(key=_sort_key, reverse=(order == "desc"))

    total = len(prows)
    if start_i > total:
        start_i = total
    page = prows[start_i:start_i + limit]
    next_i = start_i + len(page)
    has_more = next_i < total
    next_cursor = _encode_cursor(next_i, account_id) if has_more else None

    # Provide lightweight per-project counts
    task_by_project = {}
    now = _now_utc()
    for t in tasks:
        if not isinstance(t, dict):
            continue
        if t.get("account_id") != account_id:
            continue
        pid = t.get("project_id")
        if not pid:
            continue
        st = t.get("status")
        if pid not in task_by_project:
            task_by_project[pid] = {"active": 0, "done": 0, "overdue": 0}
        if st == "active":
            task_by_project[pid]["active"] += 1
            dd = _dt_from_row(t.get("due_date"))
            if dd is not None and dd < now:
                task_by_project[pid]["overdue"] += 1
        elif st == "done":
            task_by_project[pid]["done"] += 1

    data = []
    for p in page:
        pid = p.get("id")
        data.append({"project": p, "counts": task_by_project.get(pid, {"active": 0, "done": 0, "overdue": 0})})

    resp = {"object": "list", "data": data, "total": total, "has_more": has_more, "next_cursor": next_cursor}
    _log("ok", account_id=account_id, meta={"mode": "list", "returned": len(data), "total": total})
    return resp

def get_daily_productivity_overview(date=None, timezone=None, **_extra):
    import json, os, datetime, base64, time, zoneinfo, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0477000" if __import__("os").path.isdir("./environment_mix/0477000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_daily_productivity_overview"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None: return None
        if isinstance(dt, str): return dt
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _dt_from_row(v):
        if v is None: return None
        if isinstance(v, datetime.datetime):
            dt = v
        elif isinstance(v, str):
            s = v.strip()
            if not s: return None
            if s.endswith("Z"): s = s[:-1] + "+00:00"
            try: dt = datetime.datetime.fromisoformat(s)
            except ValueError: return None
        else:
            return None
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _log(status_code, account_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "account_id": account_id,
            "status": status_code,
            "latency_ms": int(round((time.time() - t0) * 1000)),
            "timestamp": _iso(_now_utc()),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _parse_date(x):
        if x is None:
            return None, None
        if not isinstance(x, str) or not x.strip() or not re.match(r"^\d{4}-\d{2}-\d{2}$", x.strip()):
            return None, _err("VALIDATION_ERROR", "date must be YYYY-MM-DD", field="date")
        return x.strip(), None

    # Ambient auth
    accounts = _load("accounts.json")
    if not isinstance(accounts, list): accounts = []
    account = None
    for st in ("active", "error", "revoked"):
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == st:
                account = a
                break
        if account:
            break
    if not account:
        e = _err("UNAUTHORIZED", "No authenticated account context is available.")
        _log("error", meta={"error": e["error"]})
        return e
    account_id = account.get("id")

    # timezone resolution
    if timezone is not None:
        if not isinstance(timezone, str) or not timezone.strip():
            e = _err("VALIDATION_ERROR", "timezone must be a valid IANA timezone name", field="timezone")
            _log("error", account_id=account_id, meta={"error": e["error"]})
            return e
        try:
            tz = zoneinfo.ZoneInfo(timezone.strip())
        except Exception:
            e = _err("VALIDATION_ERROR", "timezone must be a valid IANA timezone name", field="timezone")
            _log("error", account_id=account_id, meta={"error": e["error"]})
            return e
    else:
        tz_name = account.get("timezone")
        if isinstance(tz_name, str) and tz_name.strip():
            try:
                tz = zoneinfo.ZoneInfo(tz_name.strip())
            except Exception:
                tz = datetime.timezone.utc
        else:
            tz = datetime.timezone.utc

    day_s, de = _parse_date(date)
    if de:
        _log("error", account_id=account_id, meta={"error": de["error"]})
        return de

    now_utc = _now_utc()
    if day_s is None:
        day_local = now_utc.astimezone(tz).date()
    else:
        y, m, d = int(day_s[0:4]), int(day_s[5:7]), int(day_s[8:10])
        day_local = datetime.date(y, m, d)

    start_local = datetime.datetime(day_local.year, day_local.month, day_local.day, 0, 0, 0, tzinfo=tz)
    end_local = start_local + datetime.timedelta(days=1)
    start_utc = start_local.astimezone(datetime.timezone.utc)
    end_utc = end_local.astimezone(datetime.timezone.utc)

    tasks = _load("tasks.json")
    if not isinstance(tasks, list): tasks = []

    overdue = []
    today_scheduled = []
    completed_today = []

    # overdue: due_date < start_of_day_local, status active
    for t in tasks:
        if not isinstance(t, dict): 
            continue
        if t.get("account_id") != account_id:
            continue
        st = t.get("status")
        if st == "deleted":
            continue

        due = _dt_from_row(t.get("due_date"))
        sched = _dt_from_row(t.get("scheduled_for"))
        comp = _dt_from_row(t.get("completed_at"))

        if st == "active":
            if due is not None and due.astimezone(tz) < start_local:
                overdue.append(t)

            in_today = False
            if sched is not None and start_utc <= sched < end_utc:
                in_today = True
            if due is not None:
                due_local = due.astimezone(tz)
                if due_local.date() == day_local:
                    in_today = True
            if in_today:
                today_scheduled.append(t)

        if st == "done" and comp is not None:
            # derive local completion based on stored offset minutes if available
            off = t.get("completion_timezone_offset_minutes")
            if isinstance(off, int):
                comp_local = (comp + datetime.timedelta(minutes=off))
                if comp_local.date() == day_local:
                    completed_today.append(t)
            else:
                if start_utc <= comp < end_utc:
                    completed_today.append(t)

    resp = {
        "object": "daily_productivity_overview",
        "date": day_local.isoformat(),
        "timezone": getattr(tz, "key", None) or str(tz),
        "overdue": overdue,
        "today_scheduled": today_scheduled,
        "completed_today": completed_today,
        "counts": {"overdue": len(overdue), "today_scheduled": len(today_scheduled), "completed_today": len(completed_today)}
    }
    _log("ok", account_id=account_id, meta={"date": day_local.isoformat()})
    return resp

def batch_create_tasks(tasks, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0477000" if __import__("os").path.isdir("./environment_mix/0477000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_utc_iso():
        return _now_utc().isoformat()

    def _audit(endpoint, status_code, credential_id=None, meta=None, started=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            latency_ms = None
            if started is not None:
                latency_ms = int(round((time.time() - started) * 1000))
            logs.append({
                "id": "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": status_code,
                "latency_ms": latency_ms,
                "timestamp": _now_utc_iso(),
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _dt_parse(x):
        if x is None:
            return None
        if isinstance(x, datetime.datetime):
            return x
        if not isinstance(x, str):
            return None
        s = x.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _validate_title(title):
        if not isinstance(title, str):
            return False, "title must be a string"
        if len(title) < 1 or len(title) > 500:
            return False, "title length must be between 1 and 500"
        return True, None

    started = time.time()
    endpoint = "batch_create_tasks"

    # Validate tasks parameter
    if not isinstance(tasks, list) or len(tasks) < 1:
        _audit(endpoint, "VALIDATION_ERROR", meta={"field": "tasks"}, started=started)
        return _err("VALIDATION_ERROR", "tasks must be a non-empty array", field="tasks")
    if len(tasks) > 200:
        _audit(endpoint, "VALIDATION_ERROR", meta={"field": "tasks"}, started=started)
        return _err("VALIDATION_ERROR", "tasks exceeds maximum of 200 items", field="tasks")

    # Ambient auth: choose an account
    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    account = None
    for st in ("active", "error", "revoked"):
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == st:
                account = a
                break
        if account:
            break
    if not account:
        _audit(endpoint, "UNAUTHORIZED", started=started)
        return _err("UNAUTHORIZED", "No authenticated account context available")
    account_id = account.get("id")
    if not isinstance(account_id, str) or not account_id:
        _audit(endpoint, "UNAUTHORIZED", started=started)
        return _err("UNAUTHORIZED", "Invalid account context")

    categories = _load("categories.json")
    if not isinstance(categories, list):
        categories = []
    tasks_store = _load("tasks.json")
    if not isinstance(tasks_store, list):
        tasks_store = []

    cat_by_id = {c.get("id"): c for c in categories if isinstance(c, dict) and isinstance(c.get("id"), str)}
    task_by_id = {t.get("id"): t for t in tasks_store if isinstance(t, dict) and isinstance(t.get("id"), str)}

    cat_pat = re.compile(r"^am_cat_[0-9A-HJKMNP-TV-Z]{10,}$")
    tsk_pat = re.compile(r"^am_tsk_[0-9A-HJKMNP-TV-Z]{10,}$")

    def _normalize_due_date(dt_obj):
        # If string date-only (YYYY-MM-DD), normalize to 00:00:00 in account timezone, stored as aware UTC.
        # For batch tool, inputs are date-time; still accept date-only len==10 for robustness.
        if dt_obj is None:
            return None
        if isinstance(dt_obj, str) and re.match(r"^\d{4}-\d{2}-\d{2}$", dt_obj.strip()):
            s = dt_obj.strip()
            y, m, d = map(int, s.split("-"))
            try:
                from zoneinfo import ZoneInfo
                tzname = account.get("timezone") or "UTC"
                tz = ZoneInfo(tzname)
            except Exception:
                tz = datetime.timezone.utc
            local = datetime.datetime(y, m, d, 0, 0, 0, tzinfo=tz)
            return local.astimezone(datetime.timezone.utc)
        if isinstance(dt_obj, str):
            parsed = _dt_parse(dt_obj)
        else:
            parsed = dt_obj
        if parsed is None:
            return None
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=datetime.timezone.utc)
        return parsed.astimezone(datetime.timezone.utc)

    # Validate entire batch first (atomic)
    prepared = []
    for idx, item in enumerate(tasks):
        if not isinstance(item, dict):
            _audit(endpoint, "VALIDATION_ERROR", meta={"index": idx}, started=started)
            return _err("VALIDATION_ERROR", "Each task must be an object", index=idx)

        title = item.get("title")
        ok, msg = _validate_title(title)
        if not ok:
            _audit(endpoint, "VALIDATION_ERROR", meta={"index": idx, "field": "title"}, started=started)
            return _err("VALIDATION_ERROR", msg, index=idx, field="title")

        note = item.get("note")
        if note is not None and not isinstance(note, str):
            _audit(endpoint, "VALIDATION_ERROR", meta={"index": idx, "field": "note"}, started=started)
            return _err("VALIDATION_ERROR", "note must be a string", index=idx, field="note")

        project_id = item.get("project_id")
        category_id = item.get("category_id")
        parent_task_id = item.get("parent_task_id")
        due_date_in = item.get("due_date")
        scheduled_for_in = item.get("scheduled_for")
        priority = item.get("priority")

        if project_id is not None:
            if not isinstance(project_id, str) or not cat_pat.match(project_id):
                _audit(endpoint, "VALIDATION_ERROR", meta={"index": idx, "field": "project_id"}, started=started)
                return _err("VALIDATION_ERROR", "project_id is malformed", index=idx, field="project_id")
            c = cat_by_id.get(project_id)
            if not c or c.get("account_id") != account_id or c.get("status") == "deleted" or c.get("type") != "project":
                _audit(endpoint, "VALIDATION_ERROR", meta={"index": idx, "field": "project_id"}, started=started)
                return _err("VALIDATION_ERROR", "project_id does not reference an accessible project", index=idx, field="project_id")

        if category_id is not None:
            if not isinstance(category_id, str) or not cat_pat.match(category_id):
                _audit(endpoint, "VALIDATION_ERROR", meta={"index": idx, "field": "category_id"}, started=started)
                return _err("VALIDATION_ERROR", "category_id is malformed", index=idx, field="category_id")
            c = cat_by_id.get(category_id)
            if not c or c.get("account_id") != account_id or c.get("status") == "deleted":
                _audit(endpoint, "VALIDATION_ERROR", meta={"index": idx, "field": "category_id"}, started=started)
                return _err("VALIDATION_ERROR", "category_id does not reference an accessible category", index=idx, field="category_id")

        if parent_task_id is not None:
            if not isinstance(parent_task_id, str) or not tsk_pat.match(parent_task_id):
                _audit(endpoint, "VALIDATION_ERROR", meta={"index": idx, "field": "parent_task_id"}, started=started)
                return _err("VALIDATION_ERROR", "parent_task_id is malformed", index=idx, field="parent_task_id")
            pt = task_by_id.get(parent_task_id)
            if not pt or pt.get("account_id") != account_id or pt.get("status") == "deleted":
                _audit(endpoint, "VALIDATION_ERROR", meta={"index": idx, "field": "parent_task_id"}, started=started)
                return _err("VALIDATION_ERROR", "parent_task_id does not reference an accessible task", index=idx, field="parent_task_id")

        if due_date_in is not None:
            if not isinstance(due_date_in, str):
                _audit(endpoint, "VALIDATION_ERROR", meta={"index": idx, "field": "due_date"}, started=started)
                return _err("VALIDATION_ERROR", "due_date must be an ISO 8601 string", index=idx, field="due_date")
            nd = _normalize_due_date(due_date_in)
            if nd is None:
                _audit(endpoint, "VALIDATION_ERROR", meta={"index": idx, "field": "due_date"}, started=started)
                return _err("VALIDATION_ERROR", "due_date is invalid ISO 8601", index=idx, field="due_date")
        else:
            nd = None

        if scheduled_for_in is not None:
            if not isinstance(scheduled_for_in, str):
                _audit(endpoint, "VALIDATION_ERROR", meta={"index": idx, "field": "scheduled_for"}, started=started)
                return _err("VALIDATION_ERROR", "scheduled_for must be an ISO 8601 string", index=idx, field="scheduled_for")
            sf = _dt_parse(scheduled_for_in)
            if sf is None:
                _audit(endpoint, "VALIDATION_ERROR", meta={"index": idx, "field": "scheduled_for"}, started=started)
                return _err("VALIDATION_ERROR", "scheduled_for is invalid ISO 8601", index=idx, field="scheduled_for")
            if sf.tzinfo is None:
                sf = sf.replace(tzinfo=datetime.timezone.utc)
            sf = sf.astimezone(datetime.timezone.utc)
        else:
            sf = None

        if priority is not None:
            if not isinstance(priority, int) or priority not in (1, 2, 3, 4, 5):
                _audit(endpoint, "VALIDATION_ERROR", meta={"index": idx, "field": "priority"}, started=started)
                return _err("VALIDATION_ERROR", "priority must be one of 1..5", index=idx, field="priority")

        prepared.append({
            "title": title,
            "note": note,
            "project_id": project_id,
            "category_id": category_id,
            "parent_task_id": parent_task_id,
            "due_date": nd,
            "scheduled_for": sf,
            "priority": priority
        })

    # Create tasks
    now_iso = _now_utc_iso()
    created = []

    existing_am_ids = set()
    for t in tasks_store:
        if isinstance(t, dict) and t.get("account_id") == account_id and isinstance(t.get("am_item_id"), str):
            existing_am_ids.add(t.get("am_item_id"))

    for p in prepared:
        # Generate ids; also generate a unique am_item_id placeholder to satisfy uniqueness constraint.
        new_id = "am_tsk_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("=").replace("-", "A").replace("_", "B")
        while new_id in task_by_id:
            new_id = "am_tsk_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("=").replace("-", "A").replace("_", "B")

        new_am_item_id = "am_item_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("=")
        while new_am_item_id in existing_am_ids:
            new_am_item_id = "am_item_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("=")
        existing_am_ids.add(new_am_item_id)

        row = {
            "id": new_id,
            "account_id": account_id,
            "am_item_id": new_am_item_id,
            "title": p["title"],
            "note": p["note"],
            "project_id": p["project_id"],
            "category_id": p["category_id"],
            "parent_task_id": p["parent_task_id"],
            "due_date": p["due_date"].isoformat() if isinstance(p["due_date"], datetime.datetime) else None,
            "scheduled_for": p["scheduled_for"].isoformat() if isinstance(p["scheduled_for"], datetime.datetime) else None,
            "priority": p["priority"],
            "status": "active",
            "completed_at": None,
            "completion_timezone_offset_minutes": None,
            "reward_points_claimed": False,
            "reward_points_claimed_at": None,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        tasks_store.append(row)
        task_by_id[new_id] = row
        created.append(row)

    _save("tasks.json", tasks_store)
    _audit(endpoint, "OK", meta={"created": len(created)}, started=started)
    return {"data": created, "meta": {"created": len(created)}}

def batch_mark_done(task_ids, completed_at=None, completion_timezone_offset_minutes=None, **_extra):
    import json, os, datetime, base64, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0477000" if __import__("os").path.isdir("./environment_mix/0477000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "batch_mark_done"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None: return None
        if isinstance(dt, str): return dt
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _dt_parse_req(x, field):
        if x is None:
            return None, None
        if not isinstance(x, str) or not x.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO date-time string", field=field)
        s = x.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO date-time string", field=field)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc), None

    def _log(status_code, account_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "account_id": account_id,
            "status": status_code,
            "latency_ms": int(round((time.time() - t0) * 1000)),
            "timestamp": _iso(_now_utc()),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    # Validate task_ids: only require non-empty list; do not over-reject patterns to avoid false negatives
    if not isinstance(task_ids, list) or len(task_ids) < 1:
        e = _err("VALIDATION_ERROR", "task_ids must be a non-empty array", field="task_ids")
        _log("error", meta={"error": e["error"]})
        return e
    if len(task_ids) > 200:
        e = _err("VALIDATION_ERROR", "task_ids may not exceed 200 items", field="task_ids")
        _log("error", meta={"error": e["error"]})
        return e
    for tid in task_ids:
        if not isinstance(tid, str) or not tid.strip():
            e = _err("VALIDATION_ERROR", "each task_id must be a non-empty string", field="task_ids")
            _log("error", meta={"error": e["error"]})
            return e

    if completion_timezone_offset_minutes is not None:
        if not isinstance(completion_timezone_offset_minutes, int) or completion_timezone_offset_minutes < -840 or completion_timezone_offset_minutes > 840:
            e = _err("VALIDATION_ERROR", "completion_timezone_offset_minutes must be an integer between -840 and 840", field="completion_timezone_offset_minutes")
            _log("error", meta={"error": e["error"]})
            return e

    dt_completed, de = _dt_parse_req(completed_at, "completed_at")
    if de:
        _log("error", meta={"error": de["error"]})
        return de
    if dt_completed is None:
        dt_completed = _now_utc()

    tasks = _load("tasks.json")
    if not isinstance(tasks, list): tasks = []
    accounts = _load("accounts.json")
    if not isinstance(accounts, list): accounts = []

    # Resolve tasks; require existence for each id (NOT_FOUND if any missing)
    task_index = {}
    for i, t in enumerate(tasks):
        if isinstance(t, dict) and isinstance(t.get("id"), str):
            task_index[t["id"]] = i

    missing = [tid for tid in task_ids if tid not in task_index]
    if missing:
        e = _err("NOT_FOUND", "One or more tasks were not found", missing_task_ids=missing)
        _log("error", meta={"error": e["error"]})
        return e

    # Ensure all tasks belong to same account (since ambient auth); otherwise conflict
    account_ids = []
    for tid in task_ids:
        t = tasks[task_index[tid]]
        account_ids.append(t.get("account_id"))
    account_ids = [a for a in account_ids if isinstance(a, str)]
    if not account_ids:
        e = _err("UNAUTHORIZED", "No authenticated account context is available.")
        _log("error", meta={"error": e["error"]})
        return e
    acct = account_ids[0]
    if any(a != acct for a in account_ids):
        e = _err("CONFLICT", "All task_ids must belong to the same account context", task_ids=task_ids)
        _log("error", meta={"error": e["error"]})
        return e

    if not any(isinstance(a, dict) and a.get("id") == acct for a in accounts):
        e = _err("UNAUTHORIZED", "No authenticated account context is available.")
        _log("error", meta={"error": e["error"]})
        return e

    # Apply updates; do not mark deleted; report per-item
    updated = []
    errors = []
    changed_any = False
    now = _now_utc()
    for tid in task_ids:
        idx = task_index[tid]
        t = tasks[idx]
        if t.get("status") == "deleted":
            errors.append({"task_id": tid, "code": "INVALID_TRANSITION", "message": "Task is deleted and cannot be marked done"})
            continue

        if t.get("status") != "done":
            t["status"] = "done"
            t["completed_at"] = _iso(dt_completed)
            if completion_timezone_offset_minutes is not None:
                t["completion_timezone_offset_minutes"] = completion_timezone_offset_minutes
            elif t.get("completion_timezone_offset_minutes") is None:
                # leave as-is; schema allows null
                pass
            t["updated_at"] = _iso(now)
            tasks[idx] = t
            changed_any = True
        else:
            # idempotent: don't overwrite completed_at unless missing
            if not t.get("completed_at"):
                t["completed_at"] = _iso(dt_completed)
                changed_any = True
            if completion_timezone_offset_minutes is not None and t.get("completion_timezone_offset_minutes") != completion_timezone_offset_minutes:
                t["completion_timezone_offset_minutes"] = completion_timezone_offset_minutes
                changed_any = True
            t["updated_at"] = _iso(now)
            tasks[idx] = t

        updated.append(t)

    if changed_any:
        _save("tasks.json", tasks)

    # Must not report success with no effect if all failed
    if not updated and errors:
        e = _err("INVALID_TRANSITION", "No tasks were eligible to be marked done", errors=errors)
        _log("error", account_id=acct, meta={"error": e["error"]})
        return e

    resp = {"object": "batch_result", "updated": updated, "errors": errors, "counts": {"updated": len(updated), "errors": len(errors)}}
    _log("ok", account_id=acct, meta={"updated": len(updated), "errors": len(errors)})
    return resp

def time_tracking_summary(task_id=None, status=None, started_at_gte=None, started_at_lte=None, **_extra):
    import json, os, datetime, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0477000" if __import__("os").path.isdir("./environment_mix/0477000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.now(datetime.timezone.utc)
    endpoint = "time_tracking_summary"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO date-time string")
        try:
            # accept trailing Z
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            else:
                dt = dt.astimezone(datetime.timezone.utc)
            return dt, None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO date-time")

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            # assume already stored iso
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_stored_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            dt = v
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        if isinstance(v, str):
            ss = v.strip()
            try:
                if ss.endswith("Z"):
                    ss = ss[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(ss)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _get_account_context():
        accounts = _load("accounts.json")
        # ambient auth: choose an account that is usable (prefer active)
        for st in ("active", "error", "revoked"):
            for a in accounts:
                if isinstance(a, dict) and a.get("status") == st:
                    return a
        return None

    def _log(status_code, used_account_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        t1 = _now_utc()
        latency_ms = int(round((t1 - t0).total_seconds() * 1000))
        logs.append({
            "id": f"req_{int(t1.timestamp()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "account_id": used_account_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": _iso(t1),
        })
        _save("request_logs.json", logs)

    # validate inputs
    if task_id is not None:
        if not isinstance(task_id, str) or not re.match(r"^am_tsk_[0-9A-HJKMNP-TV-Z]{10,}$", task_id):
            acc = _get_account_context()
            _log(400, acc.get("id") if acc else None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "task_id is malformed")
    if status is not None:
        if not isinstance(status, str) or status not in ("running", "stopped", "deleted"):
            acc = _get_account_context()
            _log(400, acc.get("id") if acc else None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of: running, stopped, deleted")

    gte_dt, e = _parse_dt(started_at_gte, "started_at_gte")
    if e:
        acc = _get_account_context()
        _log(400, acc.get("id") if acc else None, "VALIDATION_ERROR")
        return e
    lte_dt, e = _parse_dt(started_at_lte, "started_at_lte")
    if e:
        acc = _get_account_context()
        _log(400, acc.get("id") if acc else None, "VALIDATION_ERROR")
        return e
    if gte_dt and lte_dt and gte_dt > lte_dt:
        acc = _get_account_context()
        _log(400, acc.get("id") if acc else None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "started_at_gte must be <= started_at_lte")

    account = _get_account_context()
    if not account or not account.get("id"):
        _log(401, None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated account context available")

    account_id = account["id"]

    sessions = _load("time_tracking.json")
    if not isinstance(sessions, list):
        sessions = []

    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []
    task_by_id = {t.get("id"): t for t in tasks if isinstance(t, dict) and t.get("id")}

    # apply filters
    filtered = []
    scanned = 0
    SCAN_CAP = 10000
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("account_id") != account_id:
            continue
        st = s.get("status")
        if st not in ("running", "stopped", "deleted"):
            continue
        scanned += 1
        if scanned > SCAN_CAP:
            _log(429, account_id, "RATE_LIMIT")
            return _err("RATE_LIMIT", "Too many time tracking sessions scanned for this request", scan_cap=SCAN_CAP)
        if status is not None and st != status:
            continue
        if task_id is not None and s.get("task_id") != task_id:
            continue
        sa = _parse_stored_dt(s.get("started_at"))
        if sa is None:
            continue
        if gte_dt and sa < gte_dt:
            continue
        if lte_dt and sa > lte_dt:
            continue
        if st == "deleted":
            # excluded by business rule unless explicitly filtered? tool allows deleted; but summary says optional status filter includes deleted.
            # If no status filter, exclude deleted by default for user-facing summary.
            if status is None:
                continue
        filtered.append(s)

    # aggregate totals by task_id and local day (account timezone)
    tzname = account.get("timezone") or "UTC"
    try:
        from zoneinfo import ZoneInfo
        tz = ZoneInfo(tzname)
    except Exception:
        tz = datetime.timezone.utc
        tzname = "UTC"

    def _local_day(dt_utc):
        if dt_utc is None:
            return None
        try:
            return dt_utc.astimezone(tz).date().isoformat()
        except Exception:
            return dt_utc.date().isoformat()

    totals = {}
    overall_seconds = 0
    running_count = 0
    for s in filtered:
        st = s.get("status")
        sa = _parse_stored_dt(s.get("started_at"))
        if sa is None:
            continue
        day = _local_day(sa)
        tid = s.get("task_id")
        dur = s.get("duration_seconds")
        if st == "running":
            running_count += 1
            # running sessions have no materialized duration; compute live duration
            dur_calc = int(round((_now_utc() - sa).total_seconds()))
            if dur_calc < 0:
                dur_calc = 0
            dur_use = dur_calc
        else:
            dur_use = dur if isinstance(dur, int) else 0
            if dur_use < 0:
                dur_use = 0
        overall_seconds += dur_use
        key = (tid, day)
        if key not in totals:
            totals[key] = {"task_id": tid, "day": day, "duration_seconds": 0, "session_count": 0}
        totals[key]["duration_seconds"] += dur_use
        totals[key]["session_count"] += 1

    # include matching sessions (not paged)
    session_out = []
    for s in sorted(filtered, key=lambda x: (_parse_stored_dt(x.get("started_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc))):
        tid = s.get("task_id")
        t = task_by_id.get(tid)
        session_out.append({
            "id": s.get("id"),
            "task_id": tid,
            "task_title": t.get("title") if isinstance(t, dict) else None,
            "status": s.get("status"),
            "started_at": s.get("started_at"),
            "stopped_at": s.get("stopped_at"),
            "duration_seconds": s.get("duration_seconds"),
            "note": s.get("note"),
            "am_time_track_id": s.get("am_time_track_id"),
            "created_at": s.get("created_at"),
            "updated_at": s.get("updated_at"),
        })

    aggregates = list(totals.values())
    aggregates.sort(key=lambda r: (r["day"] or "", r["task_id"] or ""))

    resp = {
        "timezone": tzname,
        "filters": {
            "task_id": task_id,
            "status": status,
            "started_at_gte": started_at_gte,
            "started_at_lte": started_at_lte,
        },
        "summary": {
            "total_duration_seconds": overall_seconds,
            "running_session_count": running_count,
            "aggregate_rows": len(aggregates),
            "session_rows": len(session_out),
            "sessions_scanned": scanned,
            "scan_cap": SCAN_CAP,
        },
        "aggregates": aggregates,
        "sessions": session_out,
    }
    _log(200, account_id, None)
    return resp

def get_completed_tasks(include_deleted=None, project_id=None, category_id=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, base64, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0477000" if __import__("os").path.isdir("./environment_mix/0477000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_completed_tasks"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None: return None
        if isinstance(dt, str): return dt
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _dt_from_row(v):
        if v is None: return None
        if isinstance(v, datetime.datetime):
            dt = v
        elif isinstance(v, str):
            s = v.strip()
            if not s: return None
            if s.endswith("Z"): s = s[:-1] + "+00:00"
            try: dt = datetime.datetime.fromisoformat(s)
            except ValueError: return None
        else:
            return None
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _encode_cursor(i, account_id):
        raw = json.dumps({"v": 1, "ep": endpoint, "i": i, "a": account_id}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _decode_cursor(cur, account_id):
        if cur is None:
            return 0, None
        if not isinstance(cur, str) or not cur:
            return None, _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return None, _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        if not isinstance(obj, dict) or obj.get("v") != 1 or obj.get("ep") != endpoint or obj.get("a") != account_id:
            return None, _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        i = obj.get("i")
        if not isinstance(i, int) or i < 0:
            return None, _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        return i, None

    def _log(status_code, account_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "account_id": account_id,
            "status": status_code,
            "latency_ms": int(round((time.time() - t0) * 1000)),
            "timestamp": _iso(_now_utc()),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    account = None
    for st in ("active", "error", "revoked"):
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == st:
                account = a
                break
        if account:
            break
    if not account:
        e = _err("UNAUTHORIZED", "No authenticated account context available")
        _log("error", meta={"error": e["error"]})
        return e
    account_id = account.get("id")

    if include_deleted is None:
        include_deleted = False
    if not isinstance(include_deleted, bool):
        e = _err("VALIDATION_ERROR", "include_deleted must be boolean", field="include_deleted")
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e

    if project_id is not None and (not isinstance(project_id, str) or not project_id.strip()):
        e = _err("VALIDATION_ERROR", "project_id must be a string", field="project_id")
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e
    if category_id is not None and (not isinstance(category_id, str) or not category_id.strip()):
        e = _err("VALIDATION_ERROR", "category_id must be a string", field="category_id")
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        e = _err("VALIDATION_ERROR", "limit must be between 1 and 200", field="limit")
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e

    if sort is None:
        sort = "completed_at_desc"
    if not isinstance(sort, str) or sort not in {"completed_at_desc", "completed_at_asc"}:
        e = _err("VALIDATION_ERROR", "sort is invalid", field="sort")
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e

    now = _now_utc()
    window_start = now - datetime.timedelta(days=7)

    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []

    rows = []
    for t in tasks:
        if not isinstance(t, dict):
            continue
        if t.get("account_id") != account_id:
            continue
        st = t.get("status")
        if st == "done":
            pass
        elif st == "deleted" and include_deleted:
            pass
        else:
            continue
        if project_id is not None and t.get("project_id") != project_id:
            continue
        if category_id is not None and t.get("category_id") != category_id:
            continue
        ca = _dt_from_row(t.get("completed_at"))
        if ca is None:
            continue
        if ca >= window_start:
            rows.append(t)

    rows.sort(key=lambda r: (_dt_from_row(r.get("completed_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), r.get("id") or ""), reverse=(sort == "completed_at_desc"))

    start_i, e = _decode_cursor(cursor, account_id)
    if e:
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e
    total = len(rows)
    page = rows[start_i:start_i + limit]
    next_i = start_i + len(page)
    has_more = next_i < total
    next_cursor = _encode_cursor(next_i, account_id) if has_more else None

    resp = {"tasks": page, "total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor, "window_days": 7}
    _log("ok", account_id=account_id, meta={"returned": len(page), "total": total})
    return resp

def get_productivity_summary_for_time_range(start, end, project_id=None, category_id=None, include_time_tracking=None, **_extra):
    import json, os, datetime, base64, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0477000" if __import__("os").path.isdir("./environment_mix/0477000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_productivity_summary_for_time_range"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None: return None
        if isinstance(dt, str): return dt
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _dt_parse_req(x, field):
        if not isinstance(x, str) or not x.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO date-time string", field=field)
        s = x.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO date-time string", field=field)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc), None

    def _dt_from_row(v):
        if v is None: return None
        if isinstance(v, datetime.datetime):
            dt = v
        elif isinstance(v, str):
            s = v.strip()
            if not s: return None
            if s.endswith("Z"): s = s[:-1] + "+00:00"
            try: dt = datetime.datetime.fromisoformat(s)
            except ValueError: return None
        else:
            return None
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _log(status_code, account_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "account_id": account_id,
            "status": status_code,
            "latency_ms": int(round((time.time() - t0) * 1000)),
            "timestamp": _iso(_now_utc()),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    if include_time_tracking is not None and not isinstance(include_time_tracking, bool):
        e = _err("VALIDATION_ERROR", "include_time_tracking must be a boolean", field="include_time_tracking")
        _log("error", meta={"error": e["error"]})
        return e

    if project_id is not None:
        if not isinstance(project_id, str) or not re.match(r"^am_cat_[0-9A-Z]{10,}$", project_id):
            e = _err("VALIDATION_ERROR", "project_id is malformed", field="project_id")
            _log("error", meta={"error": e["error"]})
            return e
    if category_id is not None:
        if not isinstance(category_id, str) or not re.match(r"^am_cat_[0-9A-Z]{10,}$", category_id):
            e = _err("VALIDATION_ERROR", "category_id is malformed", field="category_id")
            _log("error", meta={"error": e["error"]})
            return e

    sdt, se = _dt_parse_req(start, "start")
    if se:
        _log("error", meta={"error": se["error"]})
        return se
    edt, ee = _dt_parse_req(end, "end")
    if ee:
        _log("error", meta={"error": ee["error"]})
        return ee

    if sdt >= edt:
        e = _err("VALIDATION_ERROR", "start must be before end", field="start")
        _log("error", meta={"error": e["error"]})
        return e
    if (edt - sdt).days > 366:
        e = _err("VALIDATION_ERROR", "time range must not exceed 366 days", field="end")
        _log("error", meta={"error": e["error"]})
        return e

    # Ambient auth
    accounts = _load("accounts.json")
    if not isinstance(accounts, list): accounts = []
    account = None
    for st in ("active", "error", "revoked"):
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == st:
                account = a
                break
        if account:
            break
    if not account:
        e = _err("UNAUTHORIZED", "No authenticated account context is available.")
        _log("error", meta={"error": e["error"]})
        return e
    account_id = account.get("id")

    cats = _load("categories.json")
    if not isinstance(cats, list): cats = []
    cat_map = {c.get("id"): c for c in cats if isinstance(c, dict) and c.get("account_id") == account_id}
    if project_id is not None:
        c = cat_map.get(project_id)
        if not c or c.get("status") == "deleted":
            e = _err("NOT_FOUND", "project_id not found", project_id=project_id)
            _log("error", account_id=account_id, meta={"error": e["error"]})
            return e
    if category_id is not None:
        c = cat_map.get(category_id)
        if not c or c.get("status") == "deleted":
            e = _err("NOT_FOUND", "category_id not found", category_id=category_id)
            _log("error", account_id=account_id, meta={"error": e["error"]})
            return e

    tasks = _load("tasks.json")
    if not isinstance(tasks, list): tasks = []
    completed_tasks = []
    for t in tasks:
        if not isinstance(t, dict): 
            continue
        if t.get("account_id") != account_id:
            continue
        if t.get("status") != "done":
            continue
        if project_id is not None and t.get("project_id") != project_id:
            continue
        if category_id is not None and t.get("category_id") != category_id:
            continue
        comp = _dt_from_row(t.get("completed_at"))
        if comp is None:
            continue
        if sdt <= comp < edt:
            completed_tasks.append(t)

    summary = {
        "object": "productivity_summary",
        "start": _iso(sdt),
        "end": _iso(edt),
        "counts": {"completed_tasks": len(completed_tasks)},
        "completed_task_ids": [t.get("id") for t in completed_tasks if isinstance(t.get("id"), str)]
    }

    if include_time_tracking:
        sessions = _load("time_tracking.json")
        if not isinstance(sessions, list): sessions = []
        total_seconds = 0
        scanned = 0
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("account_id") != account_id:
                continue
            if s.get("status") not in ("running", "stopped"):
                continue
            scanned += 1
            if scanned > 10000:
                break
            st = _dt_from_row(s.get("started_at"))
            if st is None:
                continue
            # approximate: count session overlap by started_at within range (simple, offline)
            if not (sdt <= st < edt):
                continue
            dur = s.get("duration_seconds")
            if isinstance(dur, int) and dur >= 0:
                total_seconds += dur
        summary["time_tracking"] = {"total_duration_seconds": total_seconds, "sessions_scanned": scanned}

    _log("ok", account_id=account_id, meta={"completed_tasks": len(completed_tasks), "include_time_tracking": bool(include_time_tracking)})
    return summary

