        _log("error", meta={"error": e["error"]})
        return e
    if project_id is not None and (not isinstance(project_id, str) or not re.match(r"^am_cat_[0-9A-Z]{10,}$", project_id)):
        e = _err("VALIDATION_ERROR", "project_id is malformed", field="project_id")
        _log("error", meta={"error": e["error"]})
        return e
    if category_id is not None and (not isinstance(category_id, str) or not re.match(r"^am_cat_[0-9A-Z]{10,}$", category_id)):
        e = _err("VALIDATION_ERROR", "category_id is malformed", field="category_id")
        _log("error", meta={"error": e["error"]})
        return e

    # Ambient auth
    accounts = _load("accounts.json")
    if not isinstance(accounts, list): accounts = []
    account = None
    for st in ("active", "error", "revoked"):
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == st:
                account = a
                break
        if account:
            break
    if not account:
        e = _err("UNAUTHORIZED", "No authenticated account context is available.")
        _log("error", meta={"error": e["error"]})
        return e
    account_id = account.get("id")

    # timezone resolution
    if timezone is not None:
        if not isinstance(timezone, str) or not timezone.strip():
            e = _err("VALIDATION_ERROR", "timezone must be a valid IANA timezone name", field="timezone")
            _log("error", account_id=account_id, meta={"error": e["error"]})
            return e
        try:
            tz = zoneinfo.ZoneInfo(timezone.strip())
        except Exception:
            e = _err("VALIDATION_ERROR", "timezone must be a valid IANA timezone name", field="timezone")
            _log("error", account_id=account_id, meta={"error": e["error"]})
            return e
    else:
        tz_name = account.get("timezone")
        if isinstance(tz_name, str) and tz_name.strip():
            try:
                tz = zoneinfo.ZoneInfo(tz_name.strip())
            except Exception:
                tz = datetime.timezone.utc
        else:
            tz = datetime.timezone.utc

    start_i, ce = _decode_cursor(cursor, account_id)
    if ce:
        _log("error", account_id=account_id, meta={"error": ce["error"]})
        return ce

    # Validate project/category existence if provided
    cats = _load("categories.json")
    if not isinstance(cats, list): cats = []
    cat_map = {c.get("id"): c for c in cats if isinstance(c, dict) and c.get("account_id") == account_id}
    if project_id is not None:
        c = cat_map.get(project_id)
        if not c or c.get("status") == "deleted":
            e = _err("NOT_FOUND", "project_id not found", project_id=project_id)
            _log("error", account_id=account_id, meta={"error": e["error"]})
            return e
    if category_id is not None:
        c = cat_map.get(category_id)
        if not c or c.get("status") == "deleted":
            e = _err("NOT_FOUND", "category_id not found", category_id=category_id)
            _log("error", account_id=account_id, meta={"error": e["error"]})
            return e

    y, m, d = int(date[0:4]), int(date[5:7]), int(date[8:10])
    day_local = datetime.date(y, m, d)
    start_local = datetime.datetime(y, m, d, 0, 0, 0, tzinfo=tz)
    end_local = start_local + datetime.timedelta(days=1)

    tasks = _load("tasks.json")
    if not isinstance(tasks, list): tasks = []

    rows = []
    for t in tasks:
        if not isinstance(t, dict):
            continue
        if t.get("account_id") != account_id:
            continue
        if t.get("status") != "done":
            continue
        if project_id is not None and t.get("project_id") != project_id:
            continue
        if category_id is not None and t.get("category_id") != category_id:
            continue
        comp = _dt_from_row(t.get("completed_at"))
        if comp is None:
            continue
        off = t.get("completion_timezone_offset_minutes")
        if isinstance(off, int):
            comp_local = (comp + datetime.timedelta(minutes=off))
            if comp_local.date() != day_local:
                continue
        else:
            if not (start_local.astimezone(datetime.timezone.utc) <= comp < end_local.astimezone(datetime.timezone.utc)):
                continue
        rows.append(t)

    rows.sort(key=lambda t: (_dt_from_row(t.get("completed_at")) or _now_utc()), reverse=(sort == "completed_at_desc"))

    total = len(rows)
    if start_i > total:
        start_i = total
    page = rows[start_i:start_i + limit]
    next_i = start_i + len(page)
    has_more = next_i < total
    next_cursor = _encode_cursor(next_i, account_id) if has_more else None

    resp = {"object": "list", "data": page, "total": total, "has_more": has_more, "next_cursor": next_cursor}
    _log("ok", account_id=account_id, meta={"date": date, "returned": len(page), "total": total})
    return resp

def get_task(task_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0477000" if __import__("os").path.isdir("./environment_mix/0477000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat()

    def _log(endpoint, status, credential_id=None, account_id=None, error_code=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "account_id": account_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int(round((time.time() - t0) * 1000)),
            "timestamp": now_iso
        })
        _save("request_log.json", logs)

    # Ambient auth: choose an account that can serve requests (active preferred)
    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    account = None
    for a in accounts:
        if isinstance(a, dict) and a.get("status") == "active":
            account = a
            break
    if account is None:
        for a in accounts:
            if isinstance(a, dict):
                account = a
                break
    if account is None:
        _log("get_task", "error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated account context is available.")

    if not isinstance(task_id, str):
        _log("get_task", "error", account_id=account.get("id"), error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "task_id must be a string.")
    if not re.match(r"^am_tsk_[0-9A-Z]{10,}$", task_id):
        _log("get_task", "error", account_id=account.get("id"), error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "task_id format is invalid.", field="task_id")

    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []
    row = None
    for t in tasks:
        if isinstance(t, dict) and t.get("id") == task_id and t.get("account_id") == account.get("id"):
            row = t
            break

    if row is None or row.get("status") == "deleted":
        _log("get_task", "error", account_id=account.get("id"), error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Task not found.")

    _log("get_task", "ok", account_id=account.get("id"))
    return {"task": row}

def update_task(task_id, title=None, note=None, project_id=None, category_id=None, parent_task_id=None, due_date=None, scheduled_for=None, priority=None, status=None, completion_timezone_offset_minutes=None, **_extra):
    import json, os, datetime, re, time, base64, zoneinfo
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0477000" if __import__("os").path.isdir("./environment_mix/0477000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_task"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None: return None
        if isinstance(dt, str): return dt
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log(status_code, account_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "account_id": account_id,
            "status": status_code,
            "latency_ms": int(round((time.time() - t0) * 1000)),
            "timestamp": _iso(_now_utc()),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _dt_from_row(v):
        if v is None: return None
        if isinstance(v, datetime.datetime):
            dt = v
        elif isinstance(v, str):
            s = v.strip()
            if not s: return None
            if s.endswith("Z"): s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
        else:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _parse_iso_or_date(x, field, tz):
        if x is None:
            return None, None
        if x is False:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 string or null", field=field)
        if not isinstance(x, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 string or null", field=field)
        s = x.strip()
        if not s:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 string or null", field=field)
        if re.match(r"^\d{4}-\d{2}-\d{2}$", s):
            y, m, d = int(s[0:4]), int(s[5:7]), int(s[8:10])
            local_mid = datetime.datetime(y, m, d, 0, 0, 0, tzinfo=tz)
            return local_mid.astimezone(datetime.timezone.utc), None
        if s.endswith("Z"):
            s2 = s[:-1] + "+00:00"
        else:
            s2 = s
        try:
            dt = datetime.datetime.fromisoformat(s2)
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be ISO-8601 date or date-time", field=field)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc), None

    # Basic validation
    if not isinstance(task_id, str) or not task_id.strip():
        e = _err("VALIDATION_ERROR", "task_id is required and must be a string", field="task_id")
        _log("error", meta={"error": e["error"]})
        return e
    if not re.match(r"^am_tsk_[0-9A-Z]{10,}$", task_id):
        e = _err("VALIDATION_ERROR", "task_id is malformed", field="task_id")
        _log("error", meta={"error": e["error"]})
        return e
    if title is not None:
        if not isinstance(title, str):
            e = _err("VALIDATION_ERROR", "title must be a string", field="title")
            _log("error", meta={"error": e["error"]})
            return e
        if len(title) < 1 or len(title) > 500:
            e = _err("VALIDATION_ERROR", "title length must be between 1 and 500", field="title")
            _log("error", meta={"error": e["error"]})
            return e
    if note is not None:
        if not isinstance(note, str):
            e = _err("VALIDATION_ERROR", "note must be a string", field="note")
            _log("error", meta={"error": e["error"]})
            return e
        if len(note) > 20000:
            e = _err("VALIDATION_ERROR", "note length must be <= 20000", field="note")
            _log("error", meta={"error": e["error"]})
            return e
    if project_id is not None and (not isinstance(project_id, str) or not re.match(r"^am_cat_[0-9A-Z]{10,}$", project_id)):
        e = _err("VALIDATION_ERROR", "project_id is malformed", field="project_id")
        _log("error", meta={"error": e["error"]})
        return e
    if category_id is not None and (not isinstance(category_id, str) or not re.match(r"^am_cat_[0-9A-Z]{10,}$", category_id)):
        e = _err("VALIDATION_ERROR", "category_id is malformed", field="category_id")
        _log("error", meta={"error": e["error"]})
        return e
    if parent_task_id is not None and (not isinstance(parent_task_id, str) or not re.match(r"^am_tsk_[0-9A-Z]{10,}$", parent_task_id)):
        e = _err("VALIDATION_ERROR", "parent_task_id is malformed", field="parent_task_id")
        _log("error", meta={"error": e["error"]})
        return e
    if priority is not None:
        if not isinstance(priority, int) or priority < 0 or priority > 5:
            e = _err("VALIDATION_ERROR", "priority must be an integer between 0 and 5", field="priority")
            _log("error", meta={"error": e["error"]})
            return e
    if status is not None and status not in ("active", "done", "deleted"):
        e = _err("VALIDATION_ERROR", "status must be one of: active, done, deleted", field="status")
        _log("error", meta={"error": e["error"]})
        return e
    if completion_timezone_offset_minutes is not None:
        if not isinstance(completion_timezone_offset_minutes, int) or completion_timezone_offset_minutes < -840 or completion_timezone_offset_minutes > 840:
            e = _err("VALIDATION_ERROR", "completion_timezone_offset_minutes must be between -840 and 840", field="completion_timezone_offset_minutes")
            _log("error", meta={"error": e["error"]})
            return e

    tasks = _load("tasks.json")
    if not isinstance(tasks, list): tasks = []
    task = None
    idx = None
    for i, t in enumerate(tasks):
        if isinstance(t, dict) and t.get("id") == task_id:
            task = t
            idx = i
            break
    if not task:
        e = _err("NOT_FOUND", "Task not found", task_id=task_id)
        _log("error", meta={"error": e["error"]})
        return e

    accounts = _load("accounts.json")
    if not isinstance(accounts, list): accounts = []
    account_id = task.get("account_id")
    account = None
    for a in accounts:
        if isinstance(a, dict) and a.get("id") == account_id:
            account = a
            break
    if not account:
        e = _err("UNAUTHORIZED", "No authenticated account context is available for this task.")
        _log("error", meta={"error": e["error"]})
        return e

    # Determine account timezone for date-only normalization
    tz = datetime.timezone.utc
    tz_name = account.get("timezone")
    if isinstance(tz_name, str) and tz_name.strip():
        try:
            tz = zoneinfo.ZoneInfo(tz_name.strip())
        except Exception:
            tz = datetime.timezone.utc

    cats = _load("categories.json")
    if not isinstance(cats, list): cats = []
    cat_map = {c.get("id"): c for c in cats if isinstance(c, dict) and c.get("account_id") == account_id}
    task_map = {tt.get("id"): tt for tt in tasks if isinstance(tt, dict) and tt.get("account_id") == account_id}

    # Foreign key checks (must exist, same account, not deleted)
    if project_id is not None:
        c = cat_map.get(project_id)
        if not c or c.get("status") == "deleted":
            e = _err("NOT_FOUND", "project_id not found", project_id=project_id)
            _log("error", account_id=account_id, meta={"error": e["error"]})
            return e
    if category_id is not None:
        c = cat_map.get(category_id)
        if not c or c.get("status") == "deleted":
            e = _err("NOT_FOUND", "category_id not found", category_id=category_id)
            _log("error", account_id=account_id, meta={"error": e["error"]})
            return e
    if parent_task_id is not None:
        pt = task_map.get(parent_task_id)
        if not pt or pt.get("status") == "deleted":
            e = _err("NOT_FOUND", "parent_task_id not found", parent_task_id=parent_task_id)
            _log("error", account_id=account_id, meta={"error": e["error"]})
            return e
        if parent_task_id == task_id:
            e = _err("CONFLICT", "parent_task_id cannot reference the task itself", field="parent_task_id")
            _log("error", account_id=account_id, meta={"error": e["error"]})
            return e

    # Parse due_date/scheduled_for
    if due_date is not None and due_date is not None:
        if due_date is None:
            pass
    if due_date is not None:
        if due_date is None:
            parsed_due, pe = (None, None)
        else:
            parsed_due, pe = _parse_iso_or_date(due_date, "due_date", tz)
        if pe:
            _log("error", account_id=account_id, meta={"error": pe["error"]})
            return pe
    else:
        parsed_due = None

    if scheduled_for is not None:
        if scheduled_for is None:
            parsed_sched, pe = (None, None)
        else:
            parsed_sched, pe = _parse_iso_or_date(scheduled_for, "scheduled_for", tz)
        if pe:
            _log("error", account_id=account_id, meta={"error": pe["error"]})
            return pe
    else:
        parsed_sched = None

    # Apply updates
    before = dict(task)
    now = _now_utc()
    changed = False

    if title is not None and task.get("title") != title:
        task["title"] = title
        changed = True
    if note is not None and task.get("note") != note:
        task["note"] = note
        changed = True
    if project_id is not None and task.get("project_id") != project_id:
        task["project_id"] = project_id
        changed = True
    if category_id is not None and task.get("category_id") != category_id:
        task["category_id"] = category_id
        changed = True
    if parent_task_id is not None and task.get("parent_task_id") != parent_task_id:
        task["parent_task_id"] = parent_task_id
        changed = True
    if due_date is not None:
        # due_date can be null to clear
        if due_date is None:
            if task.get("due_date") is not None:
                task["due_date"] = None
                changed = True
        else:
            iso_due = _iso(parsed_due)
            if task.get("due_date") != iso_due:
                task["due_date"] = iso_due
                changed = True
    if scheduled_for is not None:
        if scheduled_for is None:
            if task.get("scheduled_for") is not None:
                task["scheduled_for"] = None
                changed = True
        else:
            iso_sched = _iso(parsed_sched)
            if task.get("scheduled_for") != iso_sched:
                task["scheduled_for"] = iso_sched
                changed = True
    if priority is not None and task.get("priority") != priority:
        task["priority"] = priority
        changed = True

    # Lifecycle transitions
    if status is not None and status != task.get("status"):
        cur = task.get("status")
        allowed = {"active": {"done", "deleted"}, "done": {"active", "deleted"}, "deleted": set()}
        if cur not in allowed or status not in allowed[cur]:
            e = _err("INVALID_TRANSITION", "Requested task status transition is not allowed", from_status=cur, to_status=status)
            _log("error", account_id=account_id, meta={"error": e["error"]})
            return e

        if status == "done":
            task["status"] = "done"
            task["completed_at"] = _iso(now)
            if completion_timezone_offset_minutes is not None:
                task["completion_timezone_offset_minutes"] = completion_timezone_offset_minutes
            else:
                # use account default offset if available
                dflt = account.get("default_timezone_offset_minutes")
                if isinstance(dflt, int) and -840 <= dflt <= 840:
                    task["completion_timezone_offset_minutes"] = dflt
            changed = True
        elif status == "active":
            task["status"] = "active"
            task["completed_at"] = None
            task["completion_timezone_offset_minutes"] = None
            # business rule: reward_points_claimed implies done; so clear when reactivating
            if task.get("reward_points_claimed"):
                task["reward_points_claimed"] = False
                task["reward_points_claimed_at"] = None
            changed = True
        elif status == "deleted":
            task["status"] = "deleted"
            changed = True

    # If setting completion offset without transitioning, ignore per tool description (only used when transitioning to done)
    if not changed:
        e = _err("NOT_FOUND", "No changes were applied (task already had the requested values).", task_id=task_id)
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e

    task["updated_at"] = _iso(now)
    tasks[idx] = task
    _save("tasks.json", tasks)

    resp = {"object": "task", "data": task}
    _log("ok", account_id=account_id, meta={"task_id": task_id, "changed_fields": [k for k in task.keys() if before.get(k) != task.get(k)]})
    return resp

