        if not isinstance(title, str) or not (1 <= len(title) <= 500):
            e = _err("VALIDATION_ERROR", "title length must be between 1 and 500", field="title")
            _log("error", meta={"error": e["error"]})
            return e
    if parent_category_id is not None:
        if not isinstance(parent_category_id, str) or not re.match(r"^am_cat_[0-9A-Z]{10,}$", parent_category_id):
            e = _err("VALIDATION_ERROR", "parent_category_id is malformed", field="parent_category_id")
            _log("error", meta={"error": e["error"]})
            return e
        if parent_category_id == category_id:
            e = _err("CONFLICT", "parent_category_id cannot reference itself", field="parent_category_id")
            _log("error", meta={"error": e["error"]})
            return e
    if color is not None:
        if not isinstance(color, str) or not re.match(r"^#?[0-9A-Fa-f]{6}$", color):
            e = _err("VALIDATION_ERROR", "color must be a 6-digit hex value", field="color")
            _log("error", meta={"error": e["error"]})
            return e
    if archived is not None and not isinstance(archived, bool):
        e = _err("VALIDATION_ERROR", "archived must be a boolean", field="archived")
        _log("error", meta={"error": e["error"]})
        return e
    if status is not None and status not in ("active", "archived", "deleted"):
        e = _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted", field="status")
        _log("error", meta={"error": e["error"]})
        return e

    cats = _load("categories.json")
    if not isinstance(cats, list): cats = []
    cat = None
    idx = None
    for i, c in enumerate(cats):
        if isinstance(c, dict) and c.get("id") == category_id:
            cat = c
            idx = i
            break
    if not cat:
        e = _err("NOT_FOUND", "Category not found", category_id=category_id)
        _log("error", meta={"error": e["error"]})
        return e

    account_id = cat.get("account_id")
    accounts = _load("accounts.json")
    if not isinstance(accounts, list): accounts = []
    if not any(isinstance(a, dict) and a.get("id") == account_id for a in accounts):
        e = _err("UNAUTHORIZED", "No authenticated account context is available for this category.")
        _log("error", meta={"error": e["error"]})
        return e

    # parent_category_id must exist, same account, not deleted
    if parent_category_id is not None:
        parent = None
        for c in cats:
            if isinstance(c, dict) and c.get("id") == parent_category_id:
                parent = c
                break
        if not parent or parent.get("account_id") != account_id or parent.get("status") == "deleted":
            e = _err("VALIDATION_ERROR", "parent_category_id must reference an existing category with the same account_id and not be deleted", field="parent_category_id")
            _log("error", account_id=account_id, meta={"error": e["error"]})
            return e

    before = dict(cat)
    now = _now_utc()
    changed = False

    if title is not None and cat.get("title") != title:
        cat["title"] = title
        changed = True
    if parent_category_id is not None and cat.get("parent_category_id") != parent_category_id:
        cat["parent_category_id"] = parent_category_id
        changed = True
    if color is not None and cat.get("color") != color:
        cat["color"] = color
        changed = True

    # archived/status consistency rule: archived=true implies status='archived'
    if archived is not None:
        if cat.get("status") == "deleted":
            e = _err("INVALID_TRANSITION", "Cannot change archived flag on a deleted category", category_id=category_id)
            _log("error", account_id=account_id, meta={"error": e["error"]})
            return e
        if cat.get("archived") != archived:
            cat["archived"] = archived
            changed = True
        if archived is True and cat.get("status") != "archived":
            # need transition to archived
            cur = cat.get("status")
            allowed = {"active": {"archived", "deleted"}, "archived": {"active", "deleted"}, "deleted": set()}
            if "archived" not in allowed.get(cur, set()):
                e = _err("INVALID_TRANSITION", "Requested category status transition is not allowed", from_status=cur, to_status="archived")
                _log("error", account_id=account_id, meta={"error": e["error"]})
                return e
            cat["status"] = "archived"
            changed = True

    if status is not None and status != cat.get("status"):
        cur = cat.get("status")
        allowed = {"active": {"archived", "deleted"}, "archived": {"active", "deleted"}, "deleted": set()}
        if status not in allowed.get(cur, set()):
            e = _err("INVALID_TRANSITION", "Requested category status transition is not allowed", from_status=cur, to_status=status)
            _log("error", account_id=account_id, meta={"error": e["error"]})
            return e
        cat["status"] = status
        changed = True
        # maintain archived flag consistency
        if status == "archived":
            cat["archived"] = True
        if status == "active":
            cat["archived"] = False

    # archived=true implies status='archived'
    if cat.get("archived") is True and cat.get("status") != "archived":
        e = _err("CONFLICT", "archived=true implies status='archived'", category_id=category_id)
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e

    if not changed:
        e = _err("NOT_FOUND", "No changes were applied (category already had the requested values).", category_id=category_id)
        _log("error", account_id=account_id, meta={"error": e["error"]})
        return e

    cat["updated_at"] = _iso(now)
    cats[idx] = cat
    _save("categories.json", cats)

    resp = {"object": "category", "data": cat}
    _log("ok", account_id=account_id, meta={"category_id": category_id, "changed_fields": [k for k in cat.keys() if before.get(k) != cat.get(k)]})
    return resp
